- އެކަލާނގެއީ އުޑުތަކާއި ބިން ހަ ދުވަހުގެ ތެރޭގައި ހެއްދެވި ރަސްކަލާނގެއެވެ. ދެން އެކަލާނގެ ޢަރްޝްގެ މައްޗަށް އިސްތިވާކުރެއްވިއެވެ. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ) 7:54; 10:3; 57:4
