- އެކަލާނގެއީ ތެދުމަގާއި ޙައްޤު ދީނާއެކު އެކަލާނގެ ރަސޫލާ ފޮނުއްވި ރަސްކަލާނގެއެވެ. އެއީ އެ ދީން ހުރިހާ ދީންތަކުގެ މައްޗަށް ފާޅުކުރެއްވުމަށްޓަކައެވެ. (هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ) 9:33; 48:28; 61:9
- "ﷲ އީ މަރްޔަމްގެ ދަރިކަލުން މަސީޙު" ކަމަށް ބުނި މީހުން ހަމަކަށްވަންކަމާއެވެ ކާފިރުވެއްޖެއެވެ. ކަލޭގެފާނު ވިދާޅުވާށެވެ. (لَّقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ قُلْ) 5:17; 5:72
- އެއުރެންގެ ފުނގެނިވުމުން ކަނުވެފައިވާ މީހުންނެވެ. ތިމަންރަސްކަލާނގެ އާޔަތްތަކަށް އީމާންވާ މީހުން މެނުވީ ކަލޭގެފާނަކަށް އިއްވެވޭކަށް ނުވެއެވެ. ފަހެ އެއުރެންނީ މުސްލިމުންނެވެ. (الْعُمْيِ عَن ضَلَالَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِآيَاتِنَا فَهُم مُّسْلِمُونَ) 27:81; 30:53
- ދުނިޔޭގެ ޙަޔާތުގެ މިސާލަކީ އުޑުން ތިމަންރަސްކަލާނގެ ބާޣުކުރެއްވި ފެނެއްގެ މިސާލެވެ. ފަހެ ބިމުގެ ގަސްތައް އެއާ އެކު އެކުވެގެންދިޔައެވެ. (مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ) 10:24; 18:45
- އެތާނގައި ކޮންމެ ދިރޭތަކެއްޗެއްގެ ދެ ޖޯޑު އަދި ކަލޭގެފާނުގެ އަހުލުވެރިން ވެއެވެ. އެއުރެންގެ މައްޗަށް ބަސްފުޅު ސާބިތުވެފައިވާ މީހުން މެނުވީއެވެ. (فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ) 11:40; 23:27
