- އަދި އެއުރެންގެ ވެރިރަސްކަލާނގެ އާޔަތްތަކުގެ ތެރެއިން އެއްވެސް އާޔަތެއް އެއުރެންނަށް އައިސްފިނަމަ އެއުރެން އެއާ އެއްކިބާވެ ނޫނީ ނުވެތެވެ. (وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ) 6:4; 36:46
- އަދި އެ ދުވަހަކާ ބިރުވެތިވާށެވެ. އެ ދުވަހު އެއްވެސް ނަފްސަކަށް އަނެއް ނަފްސަކަށް އެއްވެސް ކަމެއް ނުފުއްދަވާނެތެވެ. އަދި އެ ނަފްސުން ޝަފާޢަތެއް ޤަބޫލެއް ނުކުރައްވާނެތެވެ. (وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا) 2:48; 2:123
- ހަމަކަށްވަންކަމާއެވެ. ކަލޭގެފާނަކަށް މަރުވެފައިވާ މީހުންނަކަށް އިއްވެވޭކަށް ނުވެއެވެ. އަދި ބީރުމީހުންނަށް އެއުރެން ފުރަގަސްދީ ދާންފަށައިފިނަމަ ގޮވާލެއްވުން އިއްވެވޭކަށް ނުވެއެވެ. (إِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ) 27:80; 30:52
- ﷲ ނޫން ފަރާތަކަށް ކަތިލުގެ ގޮތުގައި ދެންނެވިފައިވާ ތަކެތި، މަރުވެފައިވާ ތަކެތި، ލޭ، އޫރުގެ މަސް އަދި މިއެނޫން ތަކެތި ތިޔަބައިމީހުންގެ މައްޗަށް ޙަރާމް ކުރައްވައިފިއެވެ. (حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ) 5:3; 16:115
- އުޑުތަކާއި ބިމުގައިވާ ހުރިހާ އެއްޗެއް ﷲ އަށް ތަސްބީޙަ ކިޔަތެވެ. އަދި އެކަލާނގެއީ ޢަޒީޒުވަންތަ ޙަކީމްވަންތަ ރަސްކަލާނގެއެވެ. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ) 59:1; 61:1
- އެއަށްފަހު ތައުބާވެ އިޞްލާޙުވި މީހުން މެނުވީއެވެ. ފަހެ ހަމަކަށްވަންކަމާއެވެ. ﷲ އީ ޣަފޫރުވަންތަ ރަޙީމްވަންތަ ރަސްކަލާނގެއެވެ. (إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) 3:89; 24:5
