- އެކަލޭގެފާނު ވިދާޅުވިއެވެ. "އޭ އަޅުގެ ޤައުމުގެ މީހުންނޭވެ. ﷲ އަށް އަޅުކަން ކުރާށެވެ. އެކަލާނގެ މެނުވީ ތިޔަބައިމީހުންނަށް އެއްވެސް އިލާހެއް ނުވެއެވެ. ފަހެ ތިޔަބައިމީހުން ތަޤުވާވެރި ނުވަނީހެއްޔެވެ؟" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23
- ﷲ އާ ދެކޮޅަށް އެއުރެންގެ މުދާތަކާއި ދަރިން އެއްވެސް ކަމެއް ފުއްދައެއް ނުދޭނެތެވެ. އަދި އެއުރެންނީ... (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކެވެ. އެތާނގައި އެއުރެން ދެމިތިބޭނެއެވެ. އަދި އެއީ ބޮޑުވެގެންވާ ކާމިޔާބީއެވެ. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- އެއުރެންގެ ކުރިން ތިބި މީހުންގެ ޚަބަރު އެއުރެންނަށް ނާދަނީހެއްޔެވެ؟ ނޫޙުގެފާނުގެ ޤައުމާއި ޢާދާއި ޘަމޫދުގެ މީހުންނެވެ. (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- "ﷲ އަށް ވާ ތިމަންނާގެ އެހީތެރިން ކޮންބައެއްތޯއެވެ؟" ޙަވާރީން ދެންނެވިއެވެ. "ތިމަންމެންނީ ﷲ ގެ އެހީތެރިންނީއެވެ. ތިމަންމެން އީމާންވެއްޖައީމެވެ." (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- ތިބާގެ ވެރިރަސްކަލާނގެ އެކަލާނގެ މަގުން ފުނގެނިގެންދާ މީހުން މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. އަދި އެކަލާނގެ ތެދުމަގު ލިބިގެންވާ މީހުން މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- އެއީ ހަމަކަށްވަންކަމާއެވެ. ﷲ އީ ޙައްޤުވަންތަ ރަސްކަލާނގެއެވެ. އަދި އެކަލާނގެ ފިޔަވައި އެއުރެން އަޅުކަންކުރާ ތަކެތި ބާޠިލެވެ. (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- އަދި ﷲ އަށާއި އެކަލާނގެ ރަސޫލާއަށް ކިޔަމަންވާ މީހާ އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކަށް އެކަލާނގެ ވައްދަވާނެއެވެ. (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- އެކަލާނގެ ތިޔަބައިމީހުންގެ މައްޗަށް ޙަރާމް ކުރެއްވީ މަރުވެފައިވާ ތަކެތި، ލޭ، އޫރުގެ މަސް އަދި ﷲ ނޫން ފަރާތަކަށް ކަތިލުގެ ގޮތުގައި ދެންނެވިފައިވާ ތަކެތިއެވެ. (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- ތިޔަބައިމީހުން ﷲ މެނުވީ އެއްވެސް ފަރާތަކަށް އަޅުކަން ނުކުރުމަށެވެ. ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނު ތިޔަބައިމީހުންގެ މައްޗަށް ދުވަހެއްގެ ޢަޛާބަށް ބިރުގަންނަމެވެ. (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- އެއީ ޣައިބުގެ ޚަބަރުތަކުގެ ތެރެއިން ތިމަންރަސްކަލާނގެ ކަލޭގެފާނަށް ވަޙީ ކުރައްވާ ޚަބަރެވެ. އަދި އެއުރެންގެ ޙަޟްރަތުގައި ކަލޭގެފާނު ވީސްފައި ނުވެއެވެ. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- ތިޔަބައިމީހުންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން ތިޔަބައިމީހުންގެ ތެރެއިން ފިރިހެނަކަށް ހަނދާންކޮށްދިނުމެއް އައުމަކާ ތިޔަބައިމީހުން ޢަޖައްބެއް ނުވަނީހެއްޔެވެ؟ އެއީ ތިޔަބައިމީހުންނަށް އިންޛާރު ކުރެއްވުމަށްޓަކައެވެ. (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- ކަލޭގެފާނު ވިދާޅުވާށެވެ. "ހަމަކަށްވަންކަމާއެވެ. ﷲ ފިޔަވައި ތިޔަބައިމީހުން އަޅުކަންކުރާ ތަކެތިން އަޅުކަން ކުރުމަން ތިމަންކަލޭގެފާނަށް ނަހީ ކުރައްވައިފިއެވެ." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- އެއުރެންގެ އަނބިން ނުވަތަ އެއުރެންގެ ކަނާތްފަރާތުގައިވާ ތަކެތި މެނުވީއެވެ. ފަހެ ހަމަކަށްވަންކަމާއެވެ. އެއުރެންނީ މަލާމާތް ލިބިގެންވާ ބައެއް ނޫނެވެ. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- ﷲ ރޭގަނޑު ދުވާލަށް ވައްދަވައި ދުވާލު ރޭގަނޑަށް ވައްދަވައެވެ. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- އަލިފާނެކެވެ. ފަހެ އެކަލޭގެފާނު އެކަލޭގެފާނުގެ އަހުލުވެރިންނަށް ވިދާޅުވިއެވެ. "ތިޔަބައިމީހުން މިތާ ތިބޭށެވެ. ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނަށް އަލިފާނެއް ފެނިއްޖެއެވެ. އެއިން ތިޔަބައިމީހުންނަށް ގެނެސްދެވިދާނެތޯއެވެ." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- އެކަލޭގެފާނު ވިދާޅުވިއެވެ. "ތިމަންކަލޭގެފާނު އެކަލޭގެފާނަށްވުރެ މާތްކަމާއެވެ. ތިމަންކަލޭގެފާނު އަލިފާނުން ހެއްދެވީއެވެ. އަދި އެކަލޭގެފާނު މަށިން ހެއްދެވީއެވެ." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- އަދި އެއުރެންނަށް "ﷲ ބާޣުކުރެއްވި ތަކެތިއާއި ރަސޫލާއާ ދިމާއަށް އަންނާށެވެ." މިފަދައިން ބުނެފިނަމަ... (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- އަދި އެއުރެންގެ މައްޗަށް ހިތާމަ ނުކުރައްވާށެވެ. އަދި އެއުރެން މަކަރު ހަދާ ކަންތަކާ މެދު ދަތިކަމެއްގައި ނުވާށެވެ. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- އަދި ﷲ ތިބާއަށް ދަތިކަމެއް ޖެއްސެވިނަމަ އެކަލާނގެ މެނުވީ އެ ދަތިކަން ނައްތާލަން އެއްވެސް ފަރާތެއް ނުވެއެވެ. އަދި ހަމަކަށްވަންކަމާއެވެ. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- އެއުރެންގެ ކުރިން ޤަރުނުތަކުގެ މީހުން އެއުރެންގެ ގެތަކުގައި ހިނގަހިނގާ އުޅުނެވެ. ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ހަމަކަށްވަންކަމާއެވެ. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- އަދި ތިމަންރަސްކަލާނގެ އެއުރެންގެ ހިތްތަކުގެ މައްޗަށް އެ ޤުރުއާން ފަހުމް ނުކުރުމަށް ފަރުދާތަކެއް ލެއްވީމެވެ. އަދި އެއުރެންގެ ކަންފަތްތަކުގައި ބީރުކަމެއް ލެއްވީމެވެ. އަދި ހަމަކަށްވަންކަމާއެވެ. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- އެއުރެންގެ ރަސޫލުން ބަޔާންވެގެންވާ ދަލީލުތަކާއެކުއެވެ. އަދި ﷲ އެއުރެންނަށް އަނިޔާއެއް ނުކުރައްވަތެވެ. އެހެނެއްކަމަކު އެއުރެން އެއުރެންގެ އަމިއްލަ ނަފްސުތަކަށް އަނިޔާ ކުރަމުން ދިޔައެވެ. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- އަދި ބިމެވެ. އަދި ﷲ ފިޔަވައި ތިޔަބައިމީހުންނަށް އެއްވެސް ރައްކާތެރިޔަކު ނުވަތަ އެހީތެރިޔަކު ނުވެއެވެ. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- ދެން ޣައިބާއި ފާޅުވެގެންވާ ކަންތައް ދެނެވޮޑިގެންވާ ރަސްކަލާނގެ ޙަޟްރަތަށް ތިޔަބައިމީހުން ރައްދު ކުރައްވާނެއެވެ. ފަހެ ތިޔަބައިމީހުން ކޮށްއުޅުނު ކަންތަކުގެ ޚަބަރު އެކަލާނގެ ތިޔަބައިމީހުންނަށް އަންގަވާނެއެވެ. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- ރޭގަނޑަކީ ތިޔަބައިމީހުން އެތާނގައި އަރާމްކުރުމަށްޓަކައެވެ. އަދި ދުވާލަކީ ފެންނަ ދުވަހެއް ކަމުގައެވެ. ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ޤައުމަކަށް ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ޢިބްރަތްތަކެއް ވެއެވެ. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- އަދި ތިބާގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން ތިބާއަށް ބާޣުކުރެއްވި ތަކެއްޗަކީ އެއުރެންގެ ތެރެއިން ގިނަބަޔެއްގެ ޠުޣްޔާނާއި ކުފުރު އިތުރުކުރާނެ ތަކެއްޗެވެ. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- އެކަލޭގެފާނު ވިދާޅުވިއެވެ. "އޭ އަޅުގެ ޤައުމުގެ މީހުންނޭވެ. ތިމަންކަލޭގެފާނު ތިމަންކަލޭގެފާނުގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން ބަޔާންވެގެންވާ ދަލީލެއްގެ މައްޗަށް ވާނަމަ އަދި އެކަލާނގެ ތިމަންކަލޭގެފާނަށް ދެއްވިނަމަ ތިޔަބައިމީހުން ދެކޭށެވެ." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- އަދި އެއުރެން ބުނެތެވެ. "އެކަލޭގެފާނުގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން އެކަލޭގެފާނަށް އާޔަތެއް ބާޣު ނުކުރައްވަނީ ކީއްވެގެންތޯއެވެ؟" ފަހެ ކަލޭގެފާނު ވިދާޅުވާށެވެ. "ހަމަކަށްވަންކަމާއެވެ." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- ﷲ ގެ ޙަޟްރަތުން އެނބުރި ދިޔުމެއް ނެތް ދުވަހެއް އައުމުގެ ކުރިންނެވެ. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- އެއީ ﷲ ގެ ފަޟްލެވެ. އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށް އެ ދެއްވައެވެ. އަދި ﷲ އީ ބޮޑުވެގެންވާ ފަޟްލު ވެރި ރަސްކަލާނގެއެވެ. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- އަދި ހަމަކަށްވަންކަމާއެވެ. ތިޔަބައިމީހުންނަށް ޖަނަވާރުތަކުގައި ޢިބްރަތެއް ވެއެވެ. އެއުރެންގެ ބަނޑުތަކުގައިވާ ތަކެތިން ތިމަންރަސްކަލާނގެ ތިޔަބައިމީހުންނަށް ބޯން ދެއްވަމެވެ. (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- އެއީ އެއުރެންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން އައި ޙައްޤު ކަމަށެވެ. އަދި ﷲ އެއުރެން ކުރާ ޢަމަލުތަކާ މެދު ޣާފިލުވެވޮޑިގެންނެއް ނުވެއެވެ. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- އެއުރެންގެ ކުރިމަތިންނާއި ފަހަތުންނެވެ. "ﷲ މެނުވީ އެއްވެސް ފަރާތަކަށް އަޅުކަން ނުކުރާށެވެ." (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- ހަމަކަށްވަންކަމާއެވެ. ތިޔަބައިމީހުން އަންހެނުން ދޫކޮށް ފިރިހެނުންނަށް ޝަހުވަތުން ގާތްވަނީއެވެ. އަދި ކިއެއްތަ؟ ތިޔަބައިމީހުންނީ ޙައްދު ފަހަނަޅައިގޮސްފައިވާ ޤައުމެކެވެ. (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- އުޑުތަކާއި ބިން ދެމިއޮތް ހައިރު އެތާނގައި ދެމިތިބޭނެއެވެ. ތިބާގެ ވެރިރަސްކަލާނގެ އިރާދަކުރެއްވި ކަމަކީ މެނުވީއެވެ. (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- އުޑުތަކުގައިވާ މީހުންނާއި ބިމުގައިވާ މީހުންނެވެ. ﷲ އިރާދަކުރެއްވި މީހަކީ މެނުވީއެވެ. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- އެތާނގައި އެއުރެންނަށް ރަނުގެ އުއްމައްޗާއި މުތްތަކުން ޒީނަތްތެރި ކުރައްވާނެއެވެ. އަދި އެތާނގައި އެއުރެންގެ ފޭރާންތަކަކީ ފަތްސެއްޗެވެ. (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
