- އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކަށް ތިމަންރަސްކަލާނގެ އެއުރެން ވައްދަވާނަމެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- ތިބާގެ ވެރިރަސްކަލާނގެ އެކަލާނގެ މަގުން ފުނގެނިގެންދާ މީހުން މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. އަދި އެކަލާނގެ މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- ޣައިބާއި ފާޅުވެގެންވާ ކަންތައް ދެނެވޮޑިގެންވާ ރަސްކަލާނގެ ޙަޟްރަތަށް ތިޔަބައިމީހުން ރައްދު ކުރައްވާނެއެވެ. ފަހެ ތިޔަބައިމީހުން ކޮށްއުޅުނު ކަންތަކުގެ ޚަބަރު އެކަލާނގެ ތިޔަބައިމީހުންނަށް އަންގަވާނެއެވެ. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- ތިޔަބައިމީހުންގެ ފިރިހެން ދަރިން ޤަތުލުކޮށް ތިޔަބައިމީހުންގެ އަންހެނުން ދިރުވައި ބަހައްޓައެވެ. އަދި އެކަމުގައި ތިޔަބައިމީހުންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން ބޮޑު އިމްތިޙާނެއް ވެއެވެ. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- ހަމަކަށްވަންކަމާއެވެ. ތިބާގެ ވެރިރަސްކަލާނގެ އެކަލާނގެ މަގުން ފުނގެނިގެންދާ މީހުން މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. އަދި އެކަލާނގެ... (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- ﷲ އީ އުޑުތަކުގައިވާ ތަކެތި އަދި ބިމުގައިވާ ތަކެތި އެކަލާނގެއަށް މިލްކުވާ ރަސްކަލާނގެއެވެ. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- ތިޔަބައިމީހުންގެ ކުރިން ފާއިތުވެގެންދިޔަ ޖިންނާއި އިންސުންގެ އުއްމަތްތަކުގެ ތެރޭގައެވެ. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- ﷲ އަށް އަޅުކަން ކުރާށެވެ. އެކަލާނގެ މެނުވީ ތިޔަބައިމީހުންނަށް އެއްވެސް އިލާހެއް ނުވެއެވެ. ފަހެ ތިޔަބައިމީހުން ތަޤުވާވެރި ނުވަނީހެއްޔެވެ؟ (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- އަދި ތިމަންރަސްކަލާނގެ އެއުރެންގެ ހިތްތަކުގެ މައްޗަށް އެ ޤުރުއާން ފަހުމް ނުކުރުމަށް ފަރުދާތަކެއް ލެއްވީމެވެ. އަދި އެއުރެންގެ ކަންފަތްތަކުގައި ބީރުކަމެއް ލެއްވީމެވެ. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- ޤިޔާމަތް ދުވަހު އެއުރެން ޚިލާފުވެއުޅުނު ކަންތަކާ މެދު އެއުރެންގެ މެދުގައި އެކަލާނގެ ޙުކުމް ކުރައްވާނެއެވެ. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- އެކަލޭގެފާނު ވިދާޅުވިއެވެ. "އޭ އަޅުގެ ޤައުމުގެ މީހުންނޭވެ. ތިމަންކަލޭގެފާނު ތިމަންކަލޭގެފާނުގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން ބަޔާންވެގެންވާ ދަލީލެއްގެ މައްޗަށް ވާނަމަ ތިޔަބައިމީހުން ދެކޭށެވެ." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- އެއީ ތިޔަބައިމީހުންގެ އަތްތައް ކުރިމަތިކުރި ކަންތަކުގެ ސަބަބުންނެވެ. އަދި ﷲ އީ އަޅުތަކުންނަށް އަނިޔާ ކުރައްވާ ރަސްކަލާނގެއެއް ނޫނެވެ. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- އެއުރެންނަށް ދުނިޔޭގައި ނިކަމެތިކަމެއް ވެއެވެ. އަދި އެއުރެންނަށް އާޚިރަތުގައި ބޮޑު ޢަޛާބެއް ވެއެވެ. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- އުޑުތަކުގައިވާ ތަކެތި އަދި ބިމުގައިވާ ތަކެތި ﷲ އަށް މިލްކުވެއެވެ. އަދި ކަންތައް ބަލަހައްޓަވާ ފަރާތެއްގެ ގޮތުން ﷲ ފުދެއެވެ. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- އީމާންވެ ޞާލިޙު ޢަމަލު ކުޅަ މީހުން މެނުވީއެވެ. އެއުރެންނަށް ނިމުމެއް ނެތް އުޖޫރައެއް ވެއެވެ. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- ތިމަންނާއާ އެކު ތިބާއަށް ޢިލްމެއް ނެތް ކަންތައް ޝަރީކު ކުރުމަށެވެ. ފަހެ އެ ދެމީހުންނަށް ކިޔަމަން ނުވާށެވެ. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- ހަމަކަށްވަންކަމާއެވެ. މިއީ ހަނދާންކޮށްދިނުމެކެވެ. ފަހެ ބޭނުންވާ މީހަކު އެމީހާގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތަށް މަގެއް ހިފާށެވެ. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- އަދި ޝުކުރު ކުރާ މީހާ ދަންނާށެވެ. ފަހެ އޭނާ ޝުކުރު ކުރަނީ އޭނާގެ އަމިއްލަ ނަފްސުގެ ފައިދާއަށެވެ. އަދި ކާފިރުވާ މީހާ ދަންނާށެވެ. ފަހެ ހަމަކަށްވަންކަމާއެވެ. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- އެއުރެންނީ ނަމާދު ޤާއިމުކޮށް ޒަކާތް ދީ އަދި އެއުރެން އާޚިރަތާ މެދު ޔަޤީންކަން ހަމަކުރާ މީހުންނެވެ. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- އިބްރާހީމާއި އިސްމާޢީލާއި އިސްޙާޤާއި ޔަޢުޤޫބާއި އަސްބާޠުންނާއި މޫސާއަށާއި ޢީސާއަށް ދެއްވި ތަކެތިއެވެ. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- ޖަމާޢަތްޖަމާޢަތަށްވެސް އެތާނގައި އެއުރެން އަންނަހިނދު އެތާނގެ ދޮރުތައް ހުޅުވޭނެއެވެ. އަދި އެތާނގެ ބަލަހައްޓަވާ ބޭކަލުން އެއުރެންނަށް ވިދާޅުވާނެއެވެ. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- ﷲ ތިޔަބައިމީހުންގެ ޤަސަމުތަކުގައި ބޭކަމެއް ނެތް ބަސްތަކުގެ ސަބަބުން ތިޔަބައިމީހުންނާ މުޢާޚަޛާ ނުކުރައްވާނެއެވެ. އެހެނެއްކަމަކު ތިޔަބައިމީހުންގެ ހިތްތައް ކުރި ކަންތަކުގެ ސަބަބުން މުޢާޚަޛާ ކުރައްވާނެއެވެ. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- ރަޙްމަތެކެވެ. ފަހެ އެއުރެން އެކަމާ އުފާކުރެތެވެ. އަދި އެއުރެންގެ އަތްތައް ކުރިމަތިކުރި ކަންތަކުގެ ސަބަބުން އެއުރެންނަށް ނުބައިކަމެއް ޖެހިއްޖެނަމައެވެ. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. އަދި ޢަމަލުކުރާ މީހުންގެ އުޖޫރަ މާތްވެގެންވެއެވެ. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- ﷲ އެވެ. އަދި އެކަލާނގެ އުޑުތަކުގައިވާ ތަކެތި އަދި ބިމުގައިވާ ތަކެތި ދެނެވޮޑިގެންވެއެވެ. އަދި ﷲ... (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- ﷲ އަށް ކިޔަމަންވާށެވެ. އަދި ރަސޫލާއަށް ކިޔަމަންވާށެވެ. ފަހެ ތިޔަބައިމީހުން އެއްކިބާވެއްޖެނަމަ ފަހެ އެކަލޭގެފާނުގެ މައްޗަށް އޮތީ... (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- އެއުރެންނަށް އެއުރެންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުގައި އެއުރެންގެ އުޖޫރަ ވެއެވެ. އަދި އެއުރެންގެ މައްޗަށް ބިރެއް ނެތެވެ. އަދި އެއުރެން... (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- އަދި އެއުރެން ބުނެތެވެ. "ތިމަންމެން ކަށިތަކަކާއި ފީނިފައިވާ ބައިބައިވެގެންދިޔައީމާ ހަމަކަށްވަންކަމާއެވެ. ތިމަންމެން އަލަށް ޚަލްޤުކުރެވިގެން އަލުން ދިރުއްވެވޭނެ ހެއްޔެވެ؟" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- އަދި ﷲ ފިޔަވައި އެއުރެންނަށް އެއްވެސް ރައްކާތެރިޔަކު ނުވަތަ އެހީތެރިޔަކު ނުފެންނާނެތެވެ. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- ތިބާ ލަހެއް ވީތޯއެވެ؟" އެކަލޭގެފާނު ވިދާޅުވިއެވެ. "ތިމަންކަލޭގެފާނު ވީީ ދުވަހެއް ނުވަތަ ދުވަހެއްގެ ބައެކެވެ." އެކަލާނގެ ވިދާޅުވިއެވެ. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- ޤިޔާމަތް ދުވަހާ ހަމަޔަށް ދެމިއޮތުމެވެ. ﷲ ފިޔަވައި ތިޔަބައިމީހުންނަށް ރޭގަނޑެއް ގެނެސްދޭނެ އިލާހަކު ހެއްޔެވެ؟ (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- ފިރިހެނަކު ނުވަތަ އަންހެނަކު ޞާލިޙު ޢަމަލެއް ކޮށް އަދި އޭނާ މުއުމިނަކު ކަމުގައިވާނަމަ... (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- ﷲ ގެ މަގުން އެއްކިބާވެ އެ މަގު ގުދަންކުރަން އިރާދަކުރާ މީހުންނެވެ. އަދި އެއުރެން އާޚިރަތާ މެދު... (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- ތިޔަބައިމީހުން ބޭނުން ތަނަކަށެވެ. އަދި މި ގަސްގަނޑަށް ގާތް ނުވާށެވެ. ފަހެ ތިޔަބައިމީހުން އަނިޔާވެރިންގެ ތެރެއިން ވެދާނެއެވެ. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- ކަލޭގެފާނު ވިދާޅުވާށެވެ. "އޭ އަޅުގެ ޤައުމުގެ މީހުންނޭވެ. ތިޔަބައިމީހުންގެ ޙާލަތުގައި ޢަމަލު ކުރާށެވެ. ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނުވެސް ޢަމަލު ކުރައްވާނަމެވެ. ފަހެ ނިކަން ތިޔަބައިމީހުންނަށް އެނގޭނެއެވެ." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- ހަމަކަށްވަންކަމާއެވެ. ޚަސާރަވެރިންނީ ޤިޔާމަތް ދުވަހު އެއުރެންގެ އަމިއްލަ ނަފްސުތަކާއި އެއުރެންގެ އަހުލުވެރިން ޚަސާރަކުޅަ މީހުންނެވެ. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- އެމީހާ އެމީހާގެ އަމިއްލަ ނަފްސުގެ ފައިދާއަށް ހިދާޔަތް ލިބިގަންނައެވެ. އަދި ފުނގެނިގެންދާ މީހާ ފުނގެނިގެންދަނީ އެމީހާގެ އަމިއްލަ ނަފްސުގެ މައްޗަށެވެ. އަދި... (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- އަދި ކާފިރުވި މީހުން ބުނެތެވެ. "އެކަލޭގެފާނުގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން އެކަލޭގެފާނަށް އާޔަތެއް ބާޣު ނުކުރައްވަނީ ކީއްވެގެންތޯއެވެ؟" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- އެކަލާނގެއީ ތިޔަބައިމީހުންނަށް ރޭގަނޑު ލެއްވި ރަސްކަލާނގެއެވެ. އެތާނގައި ތިޔަބައިމީހުން އަރާމްކުރުމަށްޓަކައެވެ. އަދި ދުވާލަކީ ފެންނަ ދުވަހެއް ކަމުގައެވެ. ހަމަކަށްވަންކަމާއެވެ. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- އެ ދުވަހެއް އައުމުގެ ކުރިންނެވެ. އެ ދުވަހު ވިޔަފާރިއެއް ނެތެވެ. އަދި... (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- އެއުރެންގެ އެކުވެރިޔާގައި މޮޔަކަމެއް ނެތް ކަމަށް އެއުރެން ވިސްނައި ފިކުރު ކުރުމަށްޓަކައެވެ. އެކަލޭގެފާނު ވިދާޅުވަނީ ހަމައެކަނި ބިރުވެރިކަމުގެ ޚަބަރު ދޭ ބޭކަލަކު ކަމުގައެވެ. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- އެތާނގައި އަބަދަށް ދެމިތިބޭނެއެވެ. އެއުރެންނަށް ޢަޛާބު ލުއި ނުކުރައްވާނެތެވެ. އަދި އެއުރެންނަށް މުހުލަތެއްވެސް ނުދެއްވާނެތެވެ. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- ތިމަންރަސްކަލާނގެ އެއުރެންގެ ތެރެއިން ބައެއް ބަޔަކަށް ދެއްވި ތަކެތިއަށް ތިބާގެ ލޯތައް ފުޅާ ނުކުރައްވާށެވެ. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- އަދި މީސްތަކުންގެ ތަކެތި އެއުރެންނަށް އުނި ނުކުރާށެވެ. އަދި ބިމުގައި ފަސާދަ ކޮށް ހަލަބިލި ނުކުރާށެވެ. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- އަދި އެކަލޭގެފާނު އުފަންވި ދުވަހާއި އެކަލޭގެފާނު މަރުވާ ދުވަހާއި އެކަލޭގެފާނު ދިރިގެން ދައްޗަވާ ދުވަހު ސަލާމް ހުށްޓެވެ. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- އޭ އަޅުގެ ޤައުމުގެ މީހުންނޭވެ. ތިޔަބައިމީހުންގެ ޙާލަތުގައި ޢަމަލު ކުރާށެވެ. ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނުވެސް ޢަމަލު ކުރައްވާނަމެވެ. ފަހެ ނިކަން ތިޔަބައިމީހުންނަށް އެނގޭނެއެވެ. ކާކުތޯއެވެ. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- އަދި ﷲ ގެ އިޛުނަފުޅާ ނުލައި އެއްވެސް ރަސޫލަކަށް އާޔަތެއް ގެނެސްދެވޭކަށް ނުވެއެވެ. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- ދެން ކޮންމެ ނަފްސަކަށްވެސް އެއާ ކުޅަ ޢަމަލުގެ ފުރިހަމަ ޖަޒާ ދެއްވާނެއެވެ. އަދި އެއުރެންނަށް އަނިޔާއެއް ނުކުރައްވާނެތެވެ. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- ފިރިހެނަކު ނުވަތަ އަންހެނަކު ކަމުގައިވެސް އަދި އޭނާ މުއުމިނަކު ކަމުގައިވާނަމަ އެއުރެން ސުވަރުގެއަށް ވަންނާނެއެވެ. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- އެކަލާނގެ ދަރިކަލަކު ނުހިއްޕަވައެވެ. އަދި ރަސްކަމުގައި އެކަލާނގެއަށް ޝަރީކަކު ނުވެއެވެ. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- އަދި ﷲ ހިދާޔަތް ދެއްވާ މީހާ އެއީ ހިދާޔަތް ލިބިގެންވާ މީހާއެވެ. އަދި އެކަލާނގެ ފުނގެންދަވާ މީހާ ދަންނާށެވެ. ފަހެ ތިބާއަކަށް ހަމަކަށް ނުފެންނާނެތެވެ. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- އެއުރެން ތިބާއަށް ދަރުބާރު ޖަހާ ގޮތް ބަލާށެވެ. ފަހެ އެއުރެން ފުނގެނިގެންފިއެވެ. ފަހެ އެއުރެންނަކަށް މަގެއް ނުފެންނާނެތެވެ. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- ކަލޭގެފާނު ވިދާޅުވާށެވެ. "ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނުގެ ވެރިރަސްކަލާނގެއަށް ނާފަރުވެރިވެއްޖެނަމަ ބޮޑު ދުވަހެއްގެ ޢަޛާބަށް ތިމަންކަލޭގެފާނު ބިރުގަންނަމެވެ." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- އެދެމީހުންގެ ޢައުރަ ފާޅުވެއްޖެއެވެ. އަދި އެދެމީހުން ސުވަރުގޭގެ ފަތްތަކުން އެދެމީހުންގެ މައްޗަށް ނުފުރާން ފެށުނެވެ. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- އަދި ތިޔަބައިމީހުން ތެދުވެރިން ކަމުގައިވާނަމަ ﷲ ފިޔަވައި ތިޔަބައިމީހުންނަށް ކުޅަދާނަވީ ފަރާތްތަކަށް ދަންނަވާށެވެ. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- ބިމުގައިވާ ހުރިހާ ތަކެތި އަދި އެއާ އެކު އެފަދަ އަނެއް ހުރިހާ ތަކެއްޗެއް އެއިން ފިދުޔަ ދިނުމަށް... (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- ތިމަންރަސްކަލާނގެ ތިޔަބައިމީހުންނަށް ދެއްވި ތަކެތި ޢަޒުމުކަމާއެކު ހިފާށެވެ. އަދި އެތާނގައިވާ ތަކެތި ހަނދާންކުރާށެވެ. އެއީ ތިޔަބައިމީހުން ތަޤުވާވެރިވުމަށްޓަކައެވެ. (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- ޢާލަމްތަކުގެ ތެރެއިން އެއްވެސް މީހަކު ތިޔަބައިމީހުންގެ ކުރިން އެ ފާޙިޝް ޢަމަލެއް ނުކުޅޭނެ ހެއްޔެވެ؟ (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- އަދި ﷲ އަށް އުޑުތަކުގައިވާ ތަކެތި އަދި ބިމުގައިވާ ތަކެތި މިލްކުވެއެވެ. އަދި ﷲ އީ ހުރިހާ ކަމެއް ދެނެވޮޑިގެންވާ ރަސްކަލާނގެއެވެ. (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- އެއުރެން ކުޅަ ޢަމަލުތަކުގެ ނުބައި ނަތީޖާތައް އެއުރެންނަށް ޖެހޭނެއެވެ. އަދި އެއުރެން ފުރައްސާރަ ކޮށްއުޅުނު ތަކެއްޗާ އެއުރެން ވަށާލެވޭނެއެވެ. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- ތިޔަބައިމީހުންގެ ތެރެއިން ރަސޫލަކު ކަމުގައިވާ ބޭކަލަކު ތިމަންރަސްކަލާނގެ އާޔަތްތައް ތިޔަބައިމީހުންނަށް ކިޔައިދެއްވައި ތިޔަބައިމީހުން ޠާހިރު ކުރައްވައި ފޮތާއި ޙިކުމަތް ތިޔަބައިމީހުންނަށް އުނގަންނައްވައެވެ. (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- އެއިން ބާރަ ފެންއާރެއް ނެރުއްވިއެވެ. ކޮންމެ ބަޔަކުވެސް އެއުރެންގެ ފެންބޯންތަން ދެނެގަތެވެ. (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- ހީކުރުން މެނުވީއެވެ. ހަމަކަށްވަންކަމާއެވެ. ހީކުރުމަކީ ޙައްޤާ ދެކޮޅަށް އެއްވެސް ކަމެއް ފުއްދައިދޭނެ އެއްޗެއް ނޫނެވެ. (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- ފަހެ ތިމަންރަސްކަލާނގެ އޭނާ ފުރިހަމަ ކުރައްވައި އަދި ތިމަންރަސްކަލާނގެ ފުރާނަފުޅުން އޭނާގެ ތެރެއަށް ފުމެލެއްވުމުން ފަހެ އޭނާއަށް ސަޖިދަ ކުރާ ޙާލު ވެއްޓޭށެވެ. (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- ފަހެ އެނިމުން ދާނެ ގޮވައްސަކީ ކާކަށްތޯއެވެ؟ ހަމަކަށްވަންކަމާއެވެ. އަނިޔާވެރިން ނާކާމިޔާބުވާނެއެވެ. (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- އެކަލާނގެއީ އުޑުތަކާއި ބިން ހެއްދެވި ރަސްކަލާނގެއެވެ. އެއުރެންފަދަ ތަކެތި ޚަލްޤު ކުރެއްވުމަށް އެކަލާނގެ ކުޅަދާނަވެވޮޑިގެންވެއެވެ. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- މުއުމިނު ފިރިހެނުންނާއި މުއުމިނު އަންހެނުންނަށް އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތައް ވެއެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
