- އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. އަދި އެއީ... (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- އޭނާގެ އުޖޫރަ އޭނާގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުގައި ވެއެވެ. އަދި އެއުރެންގެ މައްޗަށް ބިރެއް ނެތެވެ. އަދި އެއުރެން... (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- އެއުރެންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުގައެވެ. އަދި އެއުރެންގެ މައްޗަށް ބިރެއް ނެތެވެ. އަދި އެއުރެން ހިތާމަވެސް ނުކުރާނެއެވެ. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- ފަހެ ހިދާޔަތް ލިބިގަންނަ މީހާ ދަންނާށެވެ. ފަހެ އޭނާ ހިދާޔަތް ލިބިގަންނަނީ އޭނާގެ އަމިއްލަ ނަފްސުގެ ފައިދާއަށެވެ. އަދި ފުނގެނިގެންދާ މީހާ... (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- އެމީހާ އެމީހާގެ އަމިއްލަ ނަފްސުގެ ފައިދާއަށް ހިދާޔަތް ލިބިގަންނައެވެ. އަދި ފުނގެނިގެންދާ މީހާ ފުނގެނިގެންދަނީ އެމީހާގެ އަމިއްލަ ނަފްސުގެ މައްޗަށެވެ. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- އެކަލޭގެފާނުގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން އެކަލޭގެފާނަށް އާޔަތެއް ބާޣު ނުކުރައްވަނީ ކީއްވެގެންތޯއެވެ؟" ފަހެ ކަލޭގެފާނު ވިދާޅުވާށެވެ. "ހަމަކަށްވަންކަމާއެވެ." (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- އީމާންވެ ޞާލިޙު ޢަމަލު ކުޅަ މީހުންނަށް ނިމުމެއް ނެތް އުޖޫރައެއް ވެއެވެ. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- އަދި އެކަލާނގެ މަރުވެފައިވާ ތަކެއްޗިން ދިރޭ ތަކެތި ނެރުއްވައި ދިރޭ ތަކެތިން މަރުވެފައިވާ ތަކެތި ނެރުއްވައެވެ. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- އަދި ﷲ ބާޣުކުރެއްވި ގޮތަކަށް ޙުކުމް ނުކުރާ މީހުންނަކީ ފަހެ އެއުރެންނީ... (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- އެކަލާނގެ އުޑުތަކާއި ބިން އަދި އެ ދެއާ ދެމެދުގައިވާ ތަކެތި ހަ ދުވަހުގެ ތެރޭގައި ޚަލްޤު ކުރެއްވިއެވެ. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- ހަމަކަށްވަންކަމާއެވެ. ﷲ އީ މީސްތަކުންގެ މައްޗަށް ފަޟްލު ދެއްވާ ރަސްކަލާނގެއެވެ. އެހެނެއްކަމަކު މީސްތަކުންގެ ގިނަބަޔެކެވެ. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- އަދި ﷲ އެއުރެންނަށް އަނިޔާއެއް ނުކުރައްވަތެވެ. އެހެނެއްކަމަކު އެއުރެން އެއުރެންގެ އަމިއްލަ ނަފްސުތަކަށް އަނިޔާ ކުރަމުން ދިޔައެވެ. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- ތިޔަބައިމީހުންގެ ނުބައި ޢަމަލުތައް ފުހެލައްވައި އަދި އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކަށް ތިޔަބައިމީހުން ވައްދަވާނެއެވެ. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- އެކަލާނގެ ތިޔަބައިމީހުންގެ މައްޗަށް ޙަރާމް ކުރެއްވީ މަރުވެފައިވާ ތަކެތި، ލޭ، އޫރުގެ މަސް އަދި ﷲ ނޫން ފަރާތަކަށް ކަތިލުގެ ގޮތުގައި ދެންނެވިފައިވާ ތަކެތިއެވެ. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނުގެ ވެރިރަސްކަލާނގެއަށް ނާފަރުވެރިވެއްޖެނަމަ ބޮޑު ދުވަހެއްގެ ޢަޛާބަށް ތިމަންކަލޭގެފާނު ބިރުގަންނަމެވެ. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- އެއުރެންނަށް ޢިލްމު އައުމަށްފަހު އެއުރެންގެ މެދުގައިވާ ޙަސަދަވެރިކަމުން މެނުވީއެވެ. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- އަދި އެއުރެން ނަމާދު ޤާއިމުކޮށް ތިމަންރަސްކަލާނގެ އެއުރެންނަށް ދެއްވި ތަކެތިން ސިއްރާއި ފާޅުގައި ހޭދަކުރެއެވެ. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- ﷲ ފިޔަވައި ތިމަންމެންނަށް މަންފާއެއް ނުކުރާ އަދި ގެއްލުމެއްވެސް ނުދޭ ތަކެތިއެވެ. (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- އެއުރެން ތިބާއަށް ބާޣުކުރެއްވި ތަކެއްޗަށާއި ތިބާގެ ކުރިން ބާޣުކުރެއްވި ތަކެއްޗަށް އީމާންވެއެވެ. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- ﷲ އުޑުން ފެން ބާޣުކުރައްވާ ކަމެއް ތިބާ ނުދެކުނީހެއްޔެވެ؟ (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- އެކަލާނގެ ކަމެއް ނިޔާ ކުރައްވައިފިނަމަ ފަހެ އެކަމަކަށް ވިދާޅުވަނީ ހަމައެކަނި "ވާށެވެ" މިފަދައިންނެވެ. ފަހެ އެއީ ވެގެންދެއެވެ. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- އަދި މަދްޔަނަށް އެއުރެންގެ އަޚާ ޝުޢައިބުގެފާނު ފޮނުއްވީމެވެ. އެކަލޭގެފާނު ވިދާޅުވިއެވެ. "އޭ އަޅުގެ ޤައުމުގެ މީހުންނޭވެ. ﷲ އަށް އަޅުކަން ކުރާށެވެ." (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- އެއީ ޣައިބުގެ ޚަބަރުތަކުގެ ތެރެއިން ތިމަންރަސްކަލާނގެ ކަލޭގެފާނަށް ވަޙީ ކުރައްވާ ޚަބަރެވެ. އަދި ކަލޭގެފާނު ވީސްފައި ނުވެއެވެ. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- ފަހެ އެއުރެންގެ ވަޤުތު އައިސްފިނަމަ އެއުރެން އެއް ގަޑިއިރުވެސް ފަސްނުޖެހޭނެތެވެ. އަދި ކުރިންވެސް ނުޖެހޭނެތެވެ. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- އަދި ޝައިޠާނާގެ ފިޔަވަޅުތަކަށް ތަބަޢަ ނުވާށެވެ. ހަމަކަށްވަންކަމާއެވެ. އޭނާއީ ތިޔަބައިމީހުންނަށް ފާޅުވެގެންވާ ޢަދުއްވެކެވެ. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- އަދި މީސްތަކުންގެ ތެރެއިން ޢިލްމެއް ނެތި ﷲ އާ މެދު ޖަދަލުކުރާ މީހުން ވެއެވެ. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- ﷲ އެ ދެއްވަނީ އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށެވެ. އަދި ﷲ އީ ބޮޑުވެގެންވާ ފަޟްލު ވެރި ރަސްކަލާނގެއެވެ. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ކޮންމެ ނަފްސަކަށްވެސް އެއާ ކުޅަ ޢަމަލުގެ ފުރިހަމަ ޖަޒާ ދެއްވާނެއެވެ. އަދި އެއުރެންނަށް އަނިޔާއެއް ނުކުރައްވާނެތެވެ. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- އަދި ﷲ ޙަރާމް ކުރެއްވި ނަފްސެއް ޙައްޤަކާ ނުލައި ނުޤަތުލާށެވެ. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- އެކަލާނގެ ކަމެއް ނިޔާ ކުރައްވައިފިނަމަ ފަހެ އެކަމަކަށް ވިދާޅުވަނީ ހަމައެކަނި "ވާށެވެ" މިފަދައިންނެވެ. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- ފަހެ ނަރަކަމުގެ ދޮރުތަކުން ވަންނާށެވެ. އެތާނގައި އަބަދަށް ދެމިތިބޭ ޙާލުއެވެ. ފަހެ މައްޗަށް ޢުދުވާވާ މީހުންގެ ތިބޭތަން ނުބައިވެގެންވެއެވެ. (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- ފޮތުން ބައެއް ލިބިގެންވާ މީހުންނަށް ތިބާ ނުދެކުނީހެއްޔެވެ؟ (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- އެއުރެންނަށް އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތައް ވެއެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- އޭ އަޅުގެ ޤައުމުގެ މީހުންނޭވެ. ތިޔަބައިމީހުންގެ ޙާލަތުގައި ޢަމަލު ކުރާށެވެ. ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނުވެސް ޢަމަލު ކުރައްވާނަމެވެ. ފަހެ ނިކަން ތިޔަބައިމީހުންނަށް އެނގޭނެއެވެ. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- ﷲ އަށާއި އެކަލާނގެ ރަސޫލާއަށް ދެކޮޅުހެދިފި މީހާ ދަންނާށެވެ. ފަހެ ހަމަކަށްވަންކަމާއެވެ. އޭނާއަށް ނަރަކަމުގެ އަލިފާން ވެއެވެ. އެތާނގައި އަބަދަށް ދެމިތިބޭ ޙާލުއެވެ. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- އެއުރެންގެ ހިތްތަކުގެ މައްޗަށް އެ ޤުރުއާން ފަހުމް ނުކުރުމަށް ފަރުދާތަކެއް ލެއްވީމެވެ. އަދި އެއުރެންގެ ކަންފަތްތަކުގައި ބީރުކަމެއް ލެއްވީމެވެ. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- އިންޛާރު ކުރައްވާ ބޭކަލަކު އައި ކޮންމެ ރަށެއްގައިވެސް އެރަށުގެ ފުރިހަމަ ތަނަވަސް މީހުން ބުނެއެވެ. "ހަމަކަށްވަންކަމާއެވެ. ތިމަންމެން..." (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- އެއުރެން ބުނެތެވެ. "ތިމަންމެންނަށް އެއީ ކޮންއެއްޗެއްކަން ބަޔާން ކޮށްދެއްވުމަށް ތިބާގެ ވެރިރަސްކަލާނގެއަށް ދަންނަވާށެވެ." (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- އެއުރެން ބުނާނެތެވެ. "ﷲ އެވެ." ކަލޭގެފާނު ވިދާޅުވާށެވެ. "ޙަމްދު ހަމައެކަނި ﷲ އަށް މިލްކުވެއެވެ." އަދި ކިއެއްތަ؟ އެއުރެންގެ ގިނަބަޔަކު ނުދަނެތެވެ. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- އަދި އެކަލޭގެފާނުގެ ޤައުމުގެ ޖަވާބަކީ އެއުރެން "އެއުރެން ނެރުވާށެވެ." ބުނުން މެނުވީ ނުވެތެވެ. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. އެއީ ބޮޑުވެގެންވާ ކާމިޔާބީއެވެ. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- އެއުރެންނީ އެއުރެންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން ހިދާޔަތުގެ މައްޗަށް ތިބި މީހުންނެވެ. އަދި އެއުރެންނީ ކާމިޔާބު ލިބިގެންވާ މީހުންނެވެ. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- އެމީހާއަށް ނިކަމެތިކުރާ ޢަޛާބެއް އަންނާނެއެވެ. އަދި އޭނާގެ މައްޗަށް ދެމިއޮތް ޢަޛާބެއް ވެރިވާނެއެވެ. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- ފަހެ ބިމުގައި ދަތުރުކޮށް ދޮގުކުރާ މީހުންގެ ނިމުން ބަލާށެވެ. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- އެއުރެންގެ އަތްތައް ކުރިމަތިކުރި ކަންތަކުގެ ސަބަބުން އެއުރެން އެކަމަކަށް އަބަދަށް އެދެއެއް ނުކުރާނެތެވެ. އަދި ﷲ އީ އަނިޔާވެރިން ދެނެވޮޑިގެންވާ ރަސްކަލާނގެއެވެ. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- އެކަލާނގެ އެކަލާނގެ މަގުން ފުނގެނިގެންދާ މީހުން މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. އަދި އެކަލާނގެ މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- ހަމަކަށްވަންކަމާއެވެ. ﷲ އީ ތިމަންގެ ވެރިރަސްކަލާނގެއެވެ. އަދި ތިޔަބައިމީހުންގެ ވެރިރަސްކަލާނގެއެވެ. ފަހެ އެކަލާނގެއަށް އަޅުކަން ކުރާށެވެ. މިއީ ސީދާ މަގެވެ. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- މީސްތަކުންގެ މައްޗަށް ފަޟްލު ވެރިވަންތަ ރަސްކަލާނގެއެވެ. އެހެނެއްކަމަކު އެއުރެންގެ ގިނަބަޔަކު ޝުކުރެއް ނުކުރެތެވެ. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- އުޑުތަކާއި ބިމާއި އެ ދެއާ ދެމެދުގައިވާ ތަކެތި ޙައްޤަކާއި ކަނޑައެޅިފައިވާ ވަޤުތަކަކާ ނުލައި ނުހެއްދެވިއެވެ. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- ފަހެ އެއުރެން ބާޠިލު ވާހަކަ ދައްކައި ކުޅެމުން އެއުރެންނަށް ވަޢުދު ކުރެވިފައިވާ އެއުރެންގެ ދުވަހާ ބައްދަލުވާ ޙައްދަށް ދޫކޮށްލާށެވެ. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- އަދި އެއުރެން އީމާންވި މީހުންނާ ބައްދަލުވާހިނދު "ތިމަންމެން އީމާންވެއްޖައީމެވެ." ބުނެތެވެ. އަދި އެއުރެން އަމިއްލައަށް ވަންހަނދާލައިފިނަމަ... (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- އެއުރެން ތައުރާތާއި އިންޖީލާއި އެއުރެންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުން އެއުރެންނަށް ބާޣުކުރެއްވި ތަކެތި ޤާއިމުކުރެއެވެ. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- އެކަލާނގެ އެއުރެންގެ ކުރިމަތީގައިވާ ތަކެތި އަދި އެއުރެންގެ ފަހަތުގައިވާ ތަކެތި ދެނެވޮޑިގެންވެއެވެ. އަދި އެއުރެން އެއިން ވަށާލައެއް ނުލަތެވެ. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- އަދި އެކަލާނގެއީ އުޑުތަކާއި ބިން ހަ ދުވަހުގެ ތެރޭގައި ޚަލްޤު ކުރެއްވި ރަސްކަލާނގެއެވެ. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- ހަމަކަށްވަންކަމާއެވެ. އެކަމުގައި ތިޔަބައިމީހުންނަށް އާޔަތެއް ވެއެވެ. ތިޔަބައިމީހުން މުއުމިނުން ކަމުގައިވާނަމައެވެ. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- އަދި ހިދާޔަތް އައުމުން މީސްތަކުން އީމާންވުމަން އެއްވެސް ކަމަކުން މަނާއެއް ނުކުރެއެވެ. (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- އަދި އެއުރެން ﷲ އަށް އެކަލާނގެ މަގުން މީސްތަކުން ފުނގެންދާނެ ބައިވެރިން ލެއްވިއެވެ. ކަލޭގެފާނު ވިދާޅުވާށެވެ. "ތިޔަބައިމީހުން އުފާކޮށްލާށެވެ." (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- އަދި އެއުރެންގެ ތެރެއިން އިންޛާރު ކުރައްވާ ބޭކަލަކު އައުމާ އެއުރެން ޢަޖައްބެއްވެއެވެ. އަދި ކާފިރުން ބުނެތެވެ. "މިއީ..." (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- ހަމަކަށްވަންކަމާއެވެ. ތިބާގެ ވެރިރަސްކަލާނގެ އެކަލާނގެ މަގުން ފުނގެނިގެންދާ މީހުން މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- މީސްތަކުންނަށް ފެންނަން އޭނާގެ މުދާ ހޭދަކޮށް އަދި ﷲ އަށް އީމާން ނުވާ މީހާ ފަދައެވެ. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- ތިމަންރަސްކަލާނގެ ތިޔަބައިމީހުންނަށް ދެއްވި ތަކެތިން ހޭދަކުރާށެވެ. އެއްވެސް ދުވަހެއް އައުމުގެ ކުރިންނެވެ. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- އެކަލާނގެ އުޑުތަކުގައިވާ ތަކެތި އަދި ބިމުގައިވާ ތަކެތި ތިޔަބައިމީހުންނަށް ބަންދު ކުރެއްވިއެވެ. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- އަދި ހަމަކަށްވަންކަމާއެވެ. ތިމަންމެންނީ ތިޔަބައިމީހުން އެއަށް ގޮވާ ކަންތަކާ މެދު ޝައްކުގައި ވާ ބައެކެވެ. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- ހަމަކަށްވަންކަމާއެވެ. ތިބާގެ ވެރިރަސްކަލާނގެ އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށް ރިޒްޤު ތަނަވަސް ކުރައްވައި އަދި ދަތި ކުރައްވައެވެ. ހަމަކަށްވަންކަމާއެވެ. އެކަލާނގެ... (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- އުޑުތަކާއި ބިމާއި އެ ދެއާ ދެމެދުގައިވާ ތަކެތީގެ ވެރިރަސްކަލާނގެއެވެ. ތިޔަބައިމީހުން ޔަޤީންކުރާ ބައެއް ކަމުގައިވާނަމައެވެ. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- ތިމަންމެން ﷲ އަށާއި ތިމަންމެންނަށް ބާޣުކުރެއްވި ތަކެއްޗާއި ތިމަންމެންގެ ކުރިން ބާޣުކުރެއްވި ތަކެއްޗަށް އީމާންވެއްޖައީމެވެ. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- އަދި އަނިޔާވެރިވި މީހުންނަށް އަޑިގަނޑު އައިސް އެއުރެންގެ ގެތަކުގައި މަރުވެފައިވާ ޙާލު ވެއްޖައީއެވެ. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- ފަހެ އެއުރެން އެއުރެންގެ އަމިއްލަ ނަފްސުތަކާ މެދު ކުރާ ކަންތަކާ މެދު ތިޔަބައިމީހުންގެ މައްޗަށް އެއްވެސް ކުށެއް ނެތެވެ. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- ތިބާގެ ވެރިރަސްކަލާނގެ އެކަލާނގެ މަގުން ފުނގެނިގެންދާ މީހުން މާބޮޑަށް ދެނެވޮޑިގެންވެއެވެ. އަދި އެކަލާނގެ... (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- އެކަލާނގެ އަމުރުފުޅުގެ ފުރާނަފުޅާއެކު އެކަލާނގެ އަޅުތަކުންގެ ތެރެއިން އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށެވެ. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- އަދި ތިމަންރަސްކަލާނގެ މަރްޔަމްގެ ދަރިކަލުން ޢީސާއަށް ބަޔާންވެގެންވާ ދަލީލުތައް ދެއްވީމެވެ. އަދި ޤުދުސީ ފުރާނަފުޅުން އެކަލޭގެފާނަށް ވާގިވެރިވެވޮޑިގެންވެއެވެ. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- ޤިޔާމަތް ދުވަހު އެއުރެން ޚިލާފުވެއުޅުނު ކަންތަކާ މެދު އެއުރެންގެ މެދުގައި އެކަލާނގެ ޙުކުމް ކުރައްވާނެއެވެ. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- ތިމަންރަސްކަލާނގެ އެ ރަށުގެ މަތި ތިރިކުރެއްވީމެވެ. އަދި އެއުރެންގެ މައްޗަށް މަށިން ހަރުކަށި ހިލަ ވެއްސެވީމެވެ. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- ތިބާ އެއުރެންނަށް އިންޛާރު ކުރިޔަސް ނުކުރިޔަސް އެއުރެންނަށް ހަމަހަމައެވެ. އެއުރެން އީމާނެއް ނުވާނެތެވެ. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- މީސްތަކުން ދޫކޮށް ފަހެ ތިޔަބައިމީހުން ތެދުވެރިން ކަމުގައިވާނަމަ މަރަށް އެދޭށެވެ. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- ﷲ އެވެ. އެކަލާނގެ މެނުވީ ތިޔަބައިމީހުންނަށް އެއްވެސް އިލާހެއް ނުވެއެވެ. ފަހެ ތިޔަބައިމީހުން ތަޤުވާވެރި ނުވަނީހެއްޔެވެ؟ (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- އަދި ތިމަންރަސްކަލާނގެ އެއުރެންނަށް ވަޢުދު ކުރައްވާ ތަކެތިން ބައެއް ތިބާއަށް ދައްކުއްވައިފިނަމަ ނުވަތަ ތިބާ މަރުގެންނަވައިފިނަމަ ފަހެ ތިމަންރަސްކަލާނގެ ޙަޟްރަތަށެވެ. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- އެއުރެން ބުނެތެވެ. "ތިމަންމެން މަރުވެ މަށިތަކަކާއި ކަށިތަކަކަށް ވެއްޖެނަމަ ތިމަންމެން އަލުން ދިރުއްވެވޭނެ ހެއްޔެވެ؟" (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- ހަމަކަށްވަންކަމާއެވެ. ފަޟްލު ވަންތަކަން އޮތީ ﷲ ގެ އަތްޕުޅުގައެވެ. އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށް އެ ދެއްވައެވެ. އަދި ﷲ... (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- ޣައިބާއި ފާޅުވެގެންވާ ކަންތައް ދެނެވޮޑިގެންވާ ރަސްކަލާނގެ ޙަޟްރަތަށެވެ. ފަހެ ތިޔަބައިމީހުން ކޮށްއުޅުނު ކަންތަކުގެ ޚަބަރު އެކަލާނގެ ތިޔަބައިމީހުންނަށް އަންގަވާނެއެވެ. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- އޭ އީމާންވެއްޖެ މީސްތަކުންނޭވެ. ތިޔަބައިމީހުންގެ މައްޗަށް ﷲ ދެއްވި ނިޢުމަތް ހަނދާންކުރާށެވެ. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- އަދި ތިމަންރަސްކަލާނގެ ތިބާގެ ކުރިން ފިރިހެނުން މެނުވީ ފޮނުއްވައިފައި ނުވަމެވެ. އެއުރެންނަށް ތިމަންރަސްކަލާނގެ ވަޙީ ކުރައްވަމެވެ. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- އޭނާގެ ނުބައި ޢަމަލުތައް ފުހެލައްވައި އަދި އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކަށް އޭނާ ވައްދަވާނެއެވެ. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- ބަލިވެފައިވާ ނުވަތަ ދަތުރުމަތީގައިވާ މީހަކު ކަމުގައިވާނަމަ ފަހެ އެހެން ދުވަސްތަކެއްގެ ޢަދަދެކެވެ. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- އެއުރެން ހީކުރުން މެނުވީ ތަބަޢައެއް ނުވެތެވެ. އަދި އެއުރެންނީ ހީކުރާ ބައެއް މެނުވީ ނޫނެވެ. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- ﷲ އަށާއި އާޚިރަތް ދުވަހަށް އުންމީދު ކުރާ މީހަކަށް ރަނގަޅު ނަމޫނާއެކެވެ. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- އަދި ތިމަންރަސްކަލާނގެ އުޑުތަކާއި ބިމާއި އެ ދެއާ ދެމެދުގައިވާ ތަކެތި ޙައްޤަކާ ނުލައި ނުހެއްދެވީމެވެ. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- ތިބާގެ އަތް ތިބާގެ ގަމީހުގެ ތެރެއަށް ލާށެވެ. އެއީ ބަލިކަމެއް ނެތި ހުދުކޮށް ނިކުންނާނެއެވެ. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- އެކަލާނގެ އެކަލާނގެ ރަޙްމަތަށް އެކަލާނގެ އިރާދަކުރައްވާ މީހަކު ޚާއްޞަ ކުރައްވައެވެ. އަދި ﷲ އީ ބޮޑުވެގެންވާ ފަޟްލު ވެރި ރަސްކަލާނގެއެވެ. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- ﷲ އަށް އުޑުތަކާއި ބިމުގެ ރަސްކަން މިލްކުވެގެންވާ ކަން ތިބާ ނުދަންނަނީހެއްޔެވެ؟ (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- އަދި ތިޔަބައިމީހުން އަމިއްލަ ނަފްސުތަކަށްޓަކައި ކުރިމަތިކުރާ ކޮންމެ ހެޔޮ ކަމެއްވެސް ތިޔަބައިމީހުންﷲ ގެ ޙަޟްރަތުގައި ފެންނާނެތެވެ. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- އަދި ތިބާ ނިކުންނަ ކޮންމެ ތަނަކުން ތިބާގެ މޫނުފުޅު މަސްޖިދުލް ޙަރާމްގެ ދިމާއަށް ކުރައްވާށެވެ. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- ކުރިން ފާއިތުވެގެންދިޔައީއެވެ. އަދި ﷲ ގެ ސުންނަތަށް ބަދަލެއް ނުފެންނާނެތެވެ. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- އުޑުތަކުގައިވާ ތަކެތި އަދި ބިމުގައިވާ ތަކެތި އެކަލާނގެއަށް މިލްކުވެގެންވާ ރަސްކަލާނގެއެވެ. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- އަދި އެކަލާނގެ ޢިލްމާ ނުލައި އެއްވެސް އަންހެނަކު ޙާމިލައެއް ނުވެތެވެ. އަދި ވިހައެއްވެސް ނުވެތެވެ. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- ރޭގަނޑެވެ. އަދި އެކަލާނގެ އިރާއި ހަނދު ބަންނަވައި ދެއްވިއެވެ. ކޮންމެ އެއްޗެއްވެސް ކަނޑައެޅިފައިވާ ވަޤުތަކަށް ހިނގަމުންދެއެވެ. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތަކެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. އަދި އެއީ ޖަޒާއެވެ. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- އެކަލޭގެފާނު ވިދާޅުވިއެވެ. "އަދި ކިއެއްތަ؟ ތިޔަބައިމީހުންގެ ނަފްސުތައް ތިޔަބައިމީހުންނަށް ކަމަކަށް ރުހުންދީފިއެވެ. ފަހެ ރީތި ކެތްތެރިކަމެވެ." (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- އުޑުތަކުގައިވާ ތަކެތި އަދި ބިމުގައިވާ ތަކެތި އަދި ﷲ އީ... (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- އަދި އެއުރެންނަށް އެއްވެސް ރަސޫލަކު އައިސްފައި ނުވެތެވެ. އެއުރެން އެކަލޭގެފާނަށް ފުރައްސާރަ ކުރިއެވެ. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- އެއުރެން ބުނެތެވެ. "އޭ މޫސާއެވެ. ތިބާ ނުވަތަ ތިމަންމެން..." (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- އެކަލާނގެ ތިޔަބައިމީހުން މަރުގެންނަވައެވެ. އަދި ތިޔަބައިމީހުންގެ ތެރެއިން އެންމެ ދެރަ ޢުމުރަށް ރައްދުކުރެވޭ މީހުން ވެއެވެ. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- އެއުރެންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތުގައި އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތައް ވެއެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- އަދި ތިމަންރަސްކަލާނގެ އެއުރެންގެ ހިތްތަކުގެ މައްޗަށް އެ ޤުރުއާން ފަހުމް ނުކުރުމަށް ފަރުދާތަކެއް ލެއްވީމެވެ. އަދި އެއުރެންގެ ކަންފަތްތަކުގައި... (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- ހަމަކަށްވަންކަމާއެވެ. ﷲ ގެ ވަޢުދަކީ ޙައްޤެކެވެ. އެހެނެއްކަމަކު އެއުރެންގެ ގިނަބަޔަކު ނުދަނެތެވެ. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- އެއީ އެއުރެން ﷲ އާއި އެކަލާނގެ ރަސޫލާއާ ދެކޮޅުހެދިގެންނެވެ. އަދި ﷲ އާ ދެކޮޅުހަދާ މީހާ... (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- އަދި އެކަލާނގެ އެއުރެންނަށް ނިދާ ކުރައްވައި ވިދާޅުވާ ދުވަހު "ތިޔަބައިމީހުން ދަޢުވާ ކުރި ތިމަންރަސްކަލާނގެ ބައިވެރިން ކޮބައިތޯއެވެ؟" (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- ﷲ އުޑުތަކާއި ބިން ޚަލްޤު ކުރެއްވި ކަމެއް އެއުރެން ނުދެކުނީހެއްޔެވެ؟ (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- ތިބާ މަށިން ޚަލްޤު ކުރެއްވި ރަސްކަލާނގެއާއެކުއެވެ. ދެން މަނިތިއްކަކުންނެވެ. ދެން... (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- އެއުރެން ބުނީސްކަން ނުވެތެވެ. "އަޅަމެންގެ ވެރިރަސްކަލާނގެއެވެ. ތިބާ އަޅަމެންނަށް ރަސޫލަކު ނުފޮނުއްވީ ކީއްވެގެންތޯއެވެ؟ ފަހެ ތިމަންމެން ތިބާގެ އާޔަތްތަކަށް ތަބަޢަވާނެއެވެ." (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- ދެން އެއުރެންގެ ވެރިރަސްކަލާނގެ ޙަޟްރަތަށް އެއުރެން ރައްދުވާނެއެވެ. ފަހެ އެއުރެން ކޮށްއުޅުނު ކަންތަކުގެ ޚަބަރު އެކަލާނގެ އެއުރެންނަށް އަންގަވާނެއެވެ. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- އެއުރެންނަށް އެކަމާ މެދު އެއްވެސް ޢިލްމެއް ނެތެވެ. އެއުރެން ހީކުރުން މެނުވީ... (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- ހަމަކަށްވަންކަމާއެވެ. ތިމަންމެންގެ ކާބަފައިން އެއް ދީނެއްގެ މައްޗަށް ވަނިކޮށް ދެކެމެވެ. އަދި ތިމަންމެން އެއުރެންގެ ފިޔަވަޅުތަކުގައި ތަބަޢަވަމެވެ. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- ފޮތް ލިބިގެންވާ މީހުންނަށް ބަޔާންވެގެންވާ ދަލީލު އައުމަށްފަހު މެނުވީއެވެ. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- އަދި އިބްރާހީމުގެފާނު ވިދާޅުވި ހަނދާންކުރާށެވެ. "އަޅުގެ ވެރިރަސްކަލާނގެއެވެ. މި ރަށް އަމާން ރަށެއް ކުރައްވާށެވެ." (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- އަދި އެކަލާނގެ ތިޔަބައިމީހުންނަށް އިވުމާއި ފެނުމާއި ހިތްތައް ލެއްވިއެވެ. ތިޔަބައިމީހުން ޝުކުރު ކުރަނީ ވަރަށް މަދުންނެވެ. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- ﷲ ގެ އާޔަތްތަކާ މެދު އެއުރެންނަށް އައި އެއްވެސް ދަލީލެއް ނެތި ޖަދަލުކުރާ މީހުންނެވެ. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- ފަހެ ޙަޤީޤަތަށް އިންކިލާބުވެފައިވާ ޙާލު އިބްރާހީމުގެފާނުގެ ދީނަށް ތަބަޢަވާށެވެ. އަދި އެކަލޭގެފާނު މުޝްރިކުންގެ ތެރެއިން ނުވެއެވެ. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- އަދި ތިމަންރަސްކަލާނގެ ފިރުޢައުނުގެ މީހުންގެ ކިބައިން ތިޔަބައިމީހުން ސަލާމަތް ކުރެއްވި ހަނދާންކުރާށެވެ. އެއުރެން ތިޔަބައިމީހުންނަށް ނުބައި ޢަޛާބު ދެއެވެ. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- އެއީ ސީދާ ދީނެވެ. އެހެނެއްކަމަކު މީސްތަކުންގެ ގިނަބަޔަކު ނުދަނެތެވެ. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- ﷲ ތިޔަބައިމީހުންނަށް އުޑުތަކުގައިވާ ތަކެތި ބަންނަވައި ދެއްވި ކަން ތިބާ ނުދެކުނީހެއްޔެވެ؟ (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- ކާފިރުވި މީހުން ބުނާނެތެވެ. "މިއީ ފާޅުވެގެންވާ ސިޙުރެއް މެނުވީ ނޫނެވެ." (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- އަދި ތިމަންރަސްކަލާނގެ އާޔަތްތައް ބަޔާންވެގެންވާ ޙާލު އެއުރެންނަށް ކިޔައިދެއްވާހިނދު ކާފިރުވި މީހުން ބުނެތެވެ... (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ދެމިއޮތް ސުވަރުގެތަކެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- އެކަލާނގެ އިރާދަކުރައްވައެވެ. ހަމަކަށްވަންކަމާއެވެ. ﷲ އީ ހުރިހާ ކަމެއްގެ މައްޗަށް ކުޅަދާނަވަންތަ ރަސްކަލާނގެއެވެ. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- ތިޔަބައިމީހުންގެ ފާފަތައް ފުހެލައްވައި އަދި ކަނޑައެޅިފައިވާ ވަޤުތަކަށް ތިޔަބައިމީހުން ފަސްކުރެއްވުމަށެވެ. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- ތިމަންމެންގެ ކާބަފައިން އަޅުކަން ކުރި ތަކެއްޗިން ތިޔަބައިމީހުން ތިމަންމެން އެއްކިބާ ކުރަން އެދެނީހެއްޔެވެ؟ (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- އަދި ތިބާގެ ވެރިރަސްކަލާނގެ މަލާއިކަތުންނަށް ވިދާޅުވި ހަނދާންކުރާށެވެ. "ހަމަކަށްވަންކަމާއެވެ. ތިމަންރަސްކަލާނގެ މަށިން އިންސާނަކު ޚަލްޤު ކުރައްވާނަމެވެ." (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- އަދި އެކަލާނގެއީ އެކަލާނގެ ރަޙްމަތުގެ ކުރިމަތީގައި އުފާވެރި ޚަބަރުތަކެއްގެ ގޮތުގައި ވައިތައް ފޮނުއްވާ ރަސްކަލާނގެއެވެ. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- ކަލޭގެފާނު ވިދާޅުވާށެވެ. "ބިމުގައި ދަތުރުކޮށް ނިމުން ބަލާށެވެ." (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- ހަމަކަށްވަންކަމާއެވެ. އުޑުތަކާއި ބިމުގެ ޚަލްޤުގައި އަދި ރޭގަނޑާއި ދުވާލުގެ ބަދަލުވުމުގައި... (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- ﷲ އަށް ރީތި ލޯންޗެއް ދޭނީ ކާކުތޯއެވެ؟ ފަހެ އެކަލާނގެ އޭނާއަށް ގިނަގުނަ ކުރައްވާނެއެވެ. (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- ފަހެ ﷲ ބާޣުކުރެއްވި ގޮތަކަށް އެއުރެންގެ މެދުގައި ޙުކުމް ކުރައްވާށެވެ. އަދި އެއުރެންގެ ހަވަނަފުޅުތަކަށް ތަބަޢަ ނުވާށެވެ. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- އެއުރެން ބަލަނީ ހަމައެކަނި މަލާއިކަތުން އެއުރެންނަށް އައުމަށް ނުވަތަ އެކަލާނގެ އަމުރުފުޅު އައުމަށް މެނުވީހެއްޔެވެ؟ (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- ހަމަކަށްވަންކަމާއެވެ. ﷲ އާ ދިމާއަށް ދޮގު އުފައްދާ މީހުން ނާކާމިޔާބުވާނެއެވެ. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ފިރުޢައުނުގެ މީހުންނާއި އެއުރެންގެ ކުރިން ތިބި މީހުންގެ ޢާދައެކޭ އެއްފަދައިންނެވެ. އެއުރެން ތިމަންރަސްކަލާނގެ އާޔަތްތައް ދޮގުކުރޫއެވެ. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- އަދި ޞާލިޙު ޢަމަލު ކުރާ މުއުމިނުންނަށް ބޮޑު އުޖޫރައެއް ވާކަމުގެ އުފާވެރި ޚަބަރު ދެއްވާށެވެ. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- ﷲ އެކަލާނގެ އަޅުތަކުންގެ ތެރެއިން އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށް ރިޒްޤު ތަނަވަސް ކުރައްވައި އަދި ދަތި ކުރައްވައެވެ. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- އަދި ތިޔަބައިމީހުން ޣައިބާއި ފާޅުވެގެންވާ ކަންތައް ދެނެވޮޑިގެންވާ ރަސްކަލާނގެ ޙަޟްރަތަށް ރައްދު ކުރައްވާނެއެވެ. ފަހެ ތިޔަބައިމީހުން ކޮށްއުޅުނު ކަންތަކުގެ ޚަބަރު އެކަލާނގެ ތިޔަބައިމީހުންނަށް އަންގަވާނެއެވެ. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- އަދި ލޭގެ ގުޅުންތަކުގެ ބައެއް ބަޔަކު ބައެއް ބަޔަކަށްވުރެ ﷲ ގެ ފޮތުގައި ޙައްޤުވެގެންވެއެވެ. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6

cmds - Commands, Exhortations, Prohibitions, Instructions

- ފަރްޟު / ވާޖިބު (فرض / واجب) — ފަރްޟު (ކުރަންޖެހޭ؛ ދޫކޮށްލައިފިނަމަ ފާފަވާނެ)
- މުސްތަޙައްބު / މަންދޫބު (مستحب / مندوب) — މުސްތަޙައްބު (ކުރިނަމަ ޘަވާބު ލިބޭނެ، ދޫކޮށްލިނަމަ ފާފައެއް ނުވާނެ)
- މުބާޙު (مباح) — މުބާޙު (ޘަވާބެއްވެސް ނެތް، ފާފައެއްވެސް ނެތް)
- މަކްރޫހު (مكروه) — މަކްރޫހު (ނަހީ ކުރެވިފައިވާ، އެހެނެއްކަމަކު ކުރިނަމަ ފާފައެއް ނުވާނެ)
- ޙަރާމް (حرام) — ޙަރާމް (ކުރިނަމަ ފާފަވާނެ)
- ޙަލާލް (حلال، އިޒުނަ ލިބިފައިވާ / ޝަރީޢަތުގައި ހުއްދަ) އެއީ މުބާޙާއި މުސްތަޙައްބު ދެކަންވެސް ހިމެނޭ — ޙަރާމް ނޫން ކޮންމެ އެއްޗެކެވެ
- ހަމައެކަނި ﷲ އަށް އަޅުކަން ކުރުމަށާއި އެކަލާނގެ ޙަޟްރަތުން އެހީއަށް އެދުމަށެވެ. 1:5
- ހަމައެކަނި ﷲ އަށް އަޅުކަން ކުރާށެވެ. 2:21
- ﷲ އާ އެއްވެސް ބައިވެރިއެއް ނުލާށެވެ. 2:22
- ﷲ އީ ފާފަ ފުއްސަވާ (ތައުބާ ޤަބޫލު ކުރައްވާ) ރަސްކަލާނގެއެވެ. އާދަމުގެފާނު (عَلَيْهِ ٱلسَّلَامُ) ގެ ތައުބާ އެކަލާނގެ ޤަބޫލު ކުރެއްވިއެވެ. 2:37
- ޙައްޤާ ބާޠިލް ނުކުރާށެވެ. އަދި ޙައްޤު ނިކަން ނުކުރާށެވެ. 2:42
- ނަމާދު ޤާއިމު ކުރާށެވެ. އަދި ޒަކާތް ދޭށެވެ. 2:43
- އަމިއްލައަށް ޢަމަލު ކުރުމަށްފަހު އެހެން މީހުންނަށް ހެޔޮކަމަށް އަމުރު ކުރާށެވެ. 2:44
- ހުރިހާ ކަމެއްގައި ﷲ ގެ ޙަޟްރަތުން އެހީއަށް އެދޭށެވެ. 2:45
- ފަސާދަ ނުކުރާށެވެ. އަދި ފަސާދަ ނުފެތުރާށެވެ. 2:60
- މީސްތަކުން އަޅުކަންކުރާ ތަންތަނަށް ދިއުން ނުމަނާށެވެ. 2:114
- މަސްޖިދުގެ ޙުރުމަތް ދަމައިގަންނާށެވެ. ނަމާދުކުރާ ތަންތަން ޠާހިރުކޮށް ސާފުކޮށް ބަހައްޓާށެވެ. 2:125
- ﷲ ހަނދުމަ ކުރާށެވެ (ނަމާދުކޮށް، ތަސްބީޙަކޮށް ފަދަ ގޮތްތަކުން) އަދި އެކަލާނގެ ތިޔަބައިމީހުން ހަނދުމަ ކުރައްވާނެއެވެ. އަދި އެކަލާނގެއަށް ޝުކުރު ކުރާށެވެ. 2:152
- ދަތިކަމުގައި ކެތްކުރާށެވެ. 2:153
- ފާޅުވެގެންވާ ޢަދުއްވު ޝައިޠާނާގެ ފިޔަވަޅުތަކަށް ތަބަޢަ ނުވާށެވެ. 2:168
- އެއްވެސް މީހަކަށް ލޯބިވެރިކަމާއެކު ތަބަޢަ ނުވާށެވެ. 2:170
- ހުރިހާ އަމާނާތްތައް ރައްކާތެރިކޮށް އަދާ ކުރާށެވެ. ކަނޑައެޅިފައިވާ ދީނީ ވާޖިބުތައް އިޚްލާޞްތެރިކަމާއެކު އަދާ ކުރާށެވެ. ޤަސަމާއި ޢަހުދުތައް ފުއްދާށެވެ. ޚާއްޞަކޮށް ﷲ އަށް ކުރެވޭ ވަޢުދުތައް ފުއްދާށެވެ. އެހީއަށް ބޭނުންވާ މީހުންނަށް އެހީވެ ދަތިކަން ފިލުވާށެވެ. ﷲ ގެ ރަޙްމަތް ގެއްލުމަށް މެދުވެރިވާ ފާފަތަކުން ދުރުވާށެވެ. ކިބުރުވެރިކަމުން އަނިޔާއަށް ދިއުން ނުދޭށެވެ. 2:177
- ޤިޞާޞްގައި (ޢަދުލުވެރި ޖަޒާގެ ޤާނޫނުގައި) ތިޔަބައިމީހުންނަށް ދިރިހުރުމެއް ވެއެވެ. 2:179
- ރަމަޟާން މަހު ރޯދަ ހިފާށެވެ. މުއްތަޤީން (ތަޤުވާވެރިން) ކަމުގައިވުމަށް ކަނޑައެޅިފައިވާ ރޯދަ ހިފާށެވެ. 2:183
- ޤުރުއާން ހިދާޔަތުގެ އެންމެ މަތީ މަޞްދަރު ކަމުގައި ޤަދަރު ކުރާށެވެ. 2:185
- އެއްބަޔެއްގެ މުދާ އަނެއްބަޔަކު އަނިޔާވެރިކަމާއެކު ނުކާށެވެ. އަދި ޙާކިމުންނަށް (މައްސަލަ ހުށަހެޅުމުގެ ކުރިން) ރިޝްވަތް ނުދޭށެވެ. 2:188
- ބަހުންނާއި ޢަމަލުން އެހެން މީހުންނަށް އަނިޔާ ނުކުރާށެވެ. ޙަމަލާ ދޭ ފަރާތެއްގެ ގޮތުގައި ދެކޮޅުވެރިކަމެއް ނުކުރާށެވެ. ދިފާޢުގެ ގޮތުގައި މެނުވީއެވެ. 2:190
- ޔަތީމުންނަށް ރައްކާތެރިވާށެވެ. ޔަތީމުންގެ މުދާގައި އިޚްލާޞްތެރިކަމާއެކު މަސައްކަތް ކުރުމާއި އެއުރެންގެ މުދާ ނުކާށެވެ. 2:220
- ތައުބާވެ ﷲ ގެ ޙަޟްރަތުން ފާފަ ފުއްސެވުމަށް އެދޭށެވެ. ޙައިޟު ދުވަސްވަރު ޖިމާޢު ނުކުރާށެވެ. ޠާހިރުކަމާއި ސާފުކަން (ޖިސްމާނީގޮތުންނާއި ރޫޙާނީގޮތުން) ދަމައިގަންނާށެވެ. 2:222
- ޢާއިލާއާ ދިމާއަށް ތިޔަބައިމީހުންގެ ޒިންމާތައް އަދާ ކުރާށެވެ. 2:233
- ޤާބިލުކަމުގެ މައްޗަށް ބިނާކޮށް ލީޑަރުން އިޚްތިޔާރު ކުރާށެވެ. 2:247
- ދީނުގެ ކަންތަކުގައި މަޖުބޫރުކުރުން ނުވެއެވެ. 2:256
- މުދާ ޘަވާބުގެ ގޮތުގައި ހޭދަ ކުރާށެވެ. މުދާއިންނާއި ވަޤުތުން ޘަވާބު ލިބޭނެ ގޮތުގައި އެހީތެރިވާށެވެ. 2:261
- ދީލަތިކަމުން ޘަވާބު ބާޠިލް ނުކުރާށެވެ. 2:264
- ޝައިޠާނާ (ފިތުނަވެރިޔާ) ފަޤީރުކަމުން ބިރު ދައްކައި ފާޙިޝް ޢަމަލުތަކާއި ފާފަތަކަށް އަމުރު ކުރައެވެ. 2:268
- ބޭނުންޖެހިފައިވާ މީހުން ހޯދައި އެއުރެންނަށް އެހީވާށެވެ. 2:273
- ރިބާއާ ގުޅުން ނުކުރާށެވެ. ރިބާ ލިބޭ މުދާ ނުކާށެވެ. ރިބާ ނުކާށެވެ. 2:275
- ދަރިމަދުވެރިޔާ ދަތިކަމުގައިވާނަމަ އިތުރު ވަޤުތު ދޭށެވެ. 2:280
- ވިޔަފާރި މުޢާމަލާތުގައި ބަސް ދަމައިގަންނާށެވެ. މާލީ މުޢާމަލާތުގައި ތެދުވެރިވާށެވެ. ހުރިހާ އިޢުތިޤާދުތަކުގައި އިޚްލާޞްތެރިވާށެވެ. ކަނޑައެޅިފައިވާ ވަޤުތަކަށް ދަރިމަދުވެރިވެއްޖެނަމަ އެ ލިޔުއްވާށެވެ. ވިޔަފާރި އެއްބަސްވުމެއް ކުރާހިނދު ހެކިން ބަހައްޓާށެވެ. 2:282
- ހުރިހާ އަމާނާތްތައް ރައްކާތެރިކޮށް އަދާ ކުރާށެވެ. 2:283
- ބާޣުކުރެއްވި ފޮތްތަކާއި ހުރިހާ ނަބީބޭކަލުންނަށް އީމާންވާށެވެ. 2:285
- ﷲ އިންސާނަކަށް އޭނާގެ ކުޅަދާނަކަމަށްވުރެ ބޮޑު ބުރައެއް ނުޖައްސަވައެވެ. އެއުރެން ކުޅަ ހެޔޮ ޢަމަލަށް ޘަވާބު ލިބޭނެއެވެ. އަދި އެއުރެން ކުޅަ ނުބައި ޢަމަލަށް ޢަޛާބު ލިބޭނެއެވެ. ﷲ އިންސާނަކަށް އޭނާގެ ކުޅަދާނަކަމަށްވުރެ ބޮޑު ބުރައެއް ނުޖައްސަވައެވެ. އަދި ތިމަންމެންވެސް އެފަދަ ބުރައެއް ނުޖެހޭށެވެ. ދަތިކަމުގައިވެސް ﷲ ގެ ރޭއްވެވުމަށް ތަވައްކަލު ކުރާށެވެ. 2:286
- ޢަހުދުތައް ފުއްދައި ﷲ އަށް ބިރުވެތިވާ މީހުންނަށް ފަހެ ﷲ ލޯބި ކުރައްވައެވެ. 3:76
- ކުޅަދާނަކަމުގައިވާނަމަ ޙައްޖު ކުރާށެވެ. 3:97
- ބައިބައިވެ ނުގަންނާށެވެ. 3:103
- ހެޔޮކަމަށް އަމުރު ކުރައި ނުބައިކަމުން ނަހީ ކުރާށެވެ. ތިޔަބައިމީހުންގެ މުޖުތަމަޢުގައި ހެޔޮކަމަށް ބާރު އަޅާށެވެ. އެހެން މީހުން ﷲ ހަނދުމަ ކުރުމަށް ގޮވާށެވެ. 3:104
- މުއުމިނުން ތަވައްކަލު ކުރާނາީ ﷲ އަށެވެ. 3:122
- ރިބާ ނުކާށެވެ. 3:130
- ރަޙްމަތް ލިބިގަންނަން ﷲ އަށާއި އެކަލާނގެ ރަސޫލާއަށް ކިޔަމަންވާށެވެ. 3:132
- ﷲ އެކަލާނގެ މަގުގައި (ޘަވާބުގެ ޢަމަލުތަކާއި ޞަދަޤާތާއި ފަދަ ކަންކަމުގައި) ތަނަވަސްކަމާއި ދަތިކަމުގައި ހޭދަކުރާ މީހުންނަށް ލޯބި ކުރައްވައެވެ. އަދި ކޯފާ ކެޑުވައި މީސްތަކުންނަށް ޢަފޫ ކުރާ މީހުންނަށެވެ. 3:134
- ކޯފާ ކެޑުވާށެވެ. ތިޔަބައިމީހުންގެ ކޯފާ ކޮންޓްރޯލް ކުރާށެވެ. 3:134
- އެހެން މީހުންގެ ކުށްތައް ޢަފޫކޮށް ފުއްސާށެވެ. 3:135
- ބަހުން ހަރުކަށި ނުވާށެވެ. ތިބާއާ ޚިލާފުވާ މީހުންނާ ކެތްތެރިވާށެވެ. 3:159
- ﷲ ތިބާއަށް އެހީވެވޮޑިގެންފިނަމަ އެއްވެސް ފަރާތަކުން ތިބާގެ މައްޗަށް ގަދަވެއެއް ނުގަނެވޭނެއެވެ. އަދި އެކަލާނގެ ތިބާ ދޫކޮށްލައްވައިފިނަމަ ފަހެ އެކަލާނގެ ފަހުން ތިބާއަށް އެހީވެދޭނީ ކާކުތޯއެވެ؟ 3:160
- ކޮންމެ މީހަކުވެސް މަރުގެ ރަހަ ދެކޭނެއެވެ. އަދި ޤިޔާމަތް ދުވަހު މެނުވީ ތިޔަބައިމީހުންގެ އުޖޫރަ ފުރިހަމައަށް ނުދެއްވާނެއެވެ. 3:185
- ޠަބީޢަތުގެ ޢަޖާއިބުތަކާއި މި ކާއިނާތުގެ ޚަލްޤުގެ މައްޗަށް ފުންކޮށް ވިސްނާށެވެ. ﷲ މި ކާއިނާތު މާނައަކާއި މަޤްޞަދެއްގެ މައްޗަށް ޚަލްޤު ކުރެއްވި ކަން ދަންނާށެވެ. 3:191
- ފިރިހެނުންނާއި އަންހެނުންގެ ޢަމަލުތަކަށް އެއްފަދަ ޘަވާބު ވެއެވެ. 3:195
- އެއުރެންގެ ވެރިރަސްކަލާނގެއަށް ބިރުވެތިވާ މީހުންނަށް އެތާނގެ ދަށުން ފެންފޮޅުތައް ހިނގަހިނގާ ސުވަރުގެތައް ވެއެވެ. އެތާނގައި އެއުރެން އަބަދަށް ދެމިތިބޭނެއެވެ. އެއީ ﷲ ގެ ޙަޟްރަތުން ލިބޭ މަޖުމުޢެކެވެ. 3:198
- ކޮންމެ ޢަމަލެއްގައިވެސް ﷲ ގެ ރުހުން އަށް މަސައްކަތް ކުރާށެވެ. 3:200
- ތިޔަބައިމީހުންގެ ވެރިރަސްކަލާނގެއަށް ކިޔަމަންވެ އެކަލާނގެއަށް ބިރުވެތިވާށެވެ. އަދި (ގާތްތިމާގެ ގުޅުން ނުކަނޑާށެވެ.) 4:1
- ޔަތީމުންނަށް އެއުރެންގެ މުދާ ދޭށެވެ. އަދި (ތިޔަބައިމީހުންގެ) ނުބައި ތަކެތި (އެއުރެންގެ) ރަނގަޅު ތަކެއްޗާ ބަދަލެއް ނުކުރާށެވެ. އަދި އެއުރެންގެ މުދާ (ތިޔަބައިމީހުންގެ މުދާއަށް އިތުރުކޮށް) ނުކާށެވެ. 4:2
- ތިޔަބައިމީހުން ކައިވެނި ކުރާ އަންހެނުންނަށް ރަނގަޅު ހިތަކާއެކު މަހަރު (ކައިވެނީގެ ވަގުތު ފިރިމީހާ އަނބިމީހާއަށް ދޭ ފަރްޟު މަހަރު) ދޭށެވެ. 4:4
- ޔަތީމުންގެ ޙައްޤުތައް ރައްކާތެރިކުރާށެވެ. 4:6
- މަރުވެފައިވާ މީހާގެ މުދާ އޭނާގެ ޢާއިލާގެ މެންބަރުންގެ މެދުގައި ބަހަންޖެހެއެވެ. އަންހެނުންނަށް ވިރާސަތުގެ ޙައްޤު ވެއެވެ. 4:7
- ޔަތީމުންގެ މުދާ އަނިޔާވެރިކަމާއެކު ނުކާށެވެ. 4:10
- ވިރާސަތާ ބެހޭ އަމުރުތަކަށް ކިޔަމަންވާށެވެ. 4:11
- އެއުރެންގެ ރުހުމާ ނުލައި އަންހެނުންނަށް ވިރާސަތު ލިބިގަތުން ޙަރާމްވެގެންވެއެވެ. އަދި އެއުރެންނާ ހަރުކަށިކޮށް ނުހިފާށެވެ. (އަނބިންނާ) އިއްޒަތްތެރިކަމާއެކު އެކުވެރިވެ އުޅޭށެވެ. އަންހެނުންގެ ޙައްޤުތައް ޤަދަރުކޮށް ރައްކާތެރިކުރާށެވެ. ތިޔަބައިމީހުންގެ އަނބިމީހާއާ ރަޙްމަތްތެރިކަމާއި އޯގާތެރިކަމާއެކު އުޅޭށެވެ. އަންހެނުންނާ ޢިއްޒަތާއި ޢަދުލުވެރިކަމާއެކު މުޢާމަލާ ކުރާށެވެ. 4:19
- ލޭގެ ގުޅުންތަކުގެ ގާތްތިމާގެ މީހުންނާ ކައިވެނި ނުކުރާށެވެ. 4:23
- ތިޔަބައިމީހުން އަމިއްލަ ނަފްސު ނުޤަތުލާށެވެ. (އަދި އެއްބަޔަކު އަނެއްބަޔަކު ނުޤަތުލާށެވެ.) ހަމަކަށްވަންކަމާއެވެ. ﷲ އީ ތިޔަބައިމީހުންނަށް އެންމެ ރަޙްމަތްތެރި ރަސްކަލާނގެއެވެ. އެއްބަޔެއްގެ މުދާ އަނެއްބަޔަކު އަނިޔާވެރިކަމާއެކު ނުކާށެވެ. 4:29
- ނަހީ ކުރެވިފައިވާ ބޮޑެތި ފާފަތަކުން ދުރުވެއްޖެނަމަ ﷲ ތިޔަބައިމީހުންގެ (ކުދި) ފާފަތައް ފުއްސަވައި އިއްޒަތްތެރި ދޮރަކުން (ސުވަރުގެއަށް) ވައްދަވާނެއެވެ. 4:31
- ﷲ ތިޔަބައިމީހުންގެ ބައެއް މީހުންނަށް އަނެއްބައެއްގެ މައްޗަށް މާތްކުރެއްވި ކަންތަކަށް އެދުމެއް ނުކުރާށެވެ. ޙަސަދަވެރިކަމާއި ފޫހިކަމުން ދުރުވާށެވެ. 4:32
- ފިރިހެނުންނީ އަންހެނުންގެ ޙިމާޔަތްތެރިންނާއި ބެލެހެއްޓުންތެރިންނެވެ. އެއީ ﷲ އެއުރެންގެ ތެރެއިން ބައެއް ބަޔަކު އަނެއްބައެއްގެ މައްޗަށް މާތްކުރެއްވި ކަމަށާއި އެއުރެން އެއުރެންގެ މުދަލުން (އެއުރެންނަށް އެހީވުމަށް) ހޭދަކުރާ ކަމަށެވެ. ފިރިހެނާއީ ޢާއިލާގެ ޙިމާޔަތްތެރިޔާއި ބެލެހެއްޓުންތެރިޔާއެވެ. 4:34
- ﷲ އަށް އަޅުކަން ކުރައި އެކަލާނގެއާ އެއްވެސް އެއްޗެއް ޝަރީކު ނުކުރާށެވެ. މައިންބަފައިންނަށާއި ގާތްތިމާގެ މީހުންނަށާއި ޔަތީމުންނަށާއި މިސްކީނުންނަށާއި އަވަށްޓެރިޔާއަށާއި އެކުވެރިޔާއަށާއި ދަތުރުވެރިޔާއަށާއި ތިޔަބައިމީހުންގެ ކަނާތްފަރާތުގައިވާ (އަޅު) މީހުންނަށް ހެޔޮކަން ކުރާށެވެ. ކިބުރުވެރިވެ ފަޚުރުވެރިވާ މީހުންނަށް ﷲ ލޯބި ނުކުރައްވައެވެ. އެހެން މީހުންނަށް ހެޔޮކަން ކުރާށެވެ. ދެރަވެގެންވާ މީހުންނަށް ރަޙްމަތް ދައްކާށެވެ. ގާތްތިމާގެ ގުޅުން ދަމައިގަނެ ގާތްތިމާގެ މީހުންނަށް ޢިއްޒަތް ދޭށެވެ. 4:36
- މިސްކިނުވެ ނުވާށެވެ. 4:37
- ﷲ އަށް އަޅުކަމުގައި ބައިވެރިން ލެއްވުން ފުއްސަވައެއް ނުދެއްވާނެއެވެ. އެހެނެއްކަމަކު އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށް އެއިން ބޭރުގެ (ކޮންމެ ކަމެއް) ފުއްސަވައެވެ. 4:48
- އެހެން މީހުންނަށް ޙަސަދެއް ނުކުރާށެވެ. 4:54
- ﷲ އަމުރު ކުރައްވަނީ އަމާނާތްތައް އެއަށް ޙައްޤުވާ މީހުންނަށް އަދާ ކުރުމަށެވެ. އަދި މީސްތަކުންގެ މެދުގައި ޙުކުމް ކުރާހިނދު ޢަދުލުވެރިކަމާއެކު ޙުކުމް ކުރުމަށެވެ. 4:58
- ﷲ އަށާއި އެކަލާނގެ ރަސޫލާއަށް ކިޔަމަންވާށެވެ. ތިޔަބައިމީހުންގެ ތެރެއިން ވެރިންނަށް އެކަށީގެންވާ ޢިއްޒަތް ދޭށެވެ. 4:59
- ދެރަވެގެންވާ ނުވަތަ ނިކަމެތި މީހުންނަށް އަނިޔާ ނުކުރާށެވެ. 4:75
- ތިޔަބައިމީހުންނަށް ލިބޭ ކޮންމެ ހެޔޮކަމެއް ﷲ ގެ ޙަޟްރަތުންނެވެ. އަދި ތިޔަބައިމީހުންނަށް ޖެހޭ ކޮންމެ ނުބައިކަމެއް ތިޔަބައިމީހުންގެ އަމިއްލަ ނަފްސުންނެވެ. 4:79
- ރަސޫލާ (މުޙައްމަދު ﷺ) އަށް ކިޔަމަންވާ މީހާ ހަމަކަށްވަންކަމާއެވެ. ﷲ އަށް ކިޔަމަންވެއްޖެއެވެ. 4:80
- ހެޔޮ ކަމަކަށް ޝަފާޢަތް ކުރާ މީހަކަށް އެކަމުގެ ޘަވާބު ލިބޭނެއެވެ. އަދި ނުބައި ކަމަކަށް ޝަފާޢަތް ކުރާ މީހަކަށް އެކަމުގެ ބައެއް ލިބޭނެއެވެ. 4:85
- މުއުމިނަކު މުއުމިނަކު ޤަތުލު ކުރުން ހުއްދައެއް ނުވެއެވެ. (ކުށެއް ނެތި) ޣަލަތަކުން މެނުވީއެވެ. 4:92
- މުއުމިނަކު ކުއްލިޔަކު ޤަތުލު ކޮށްފި މީހާގެ ޖަޒާއަކީ ނަރަކަމެވެ. އެތާނގައި އަބަދަށް ދެމިތިބޭ ޙާލުއެވެ. ﷲ ގެ ކޯފާއާއި ލަޢުނަތް އޭނާގެ މައްޗަށް ވެއެވެ. އަދި އޭނާއަށް ބޮޑު ޢަޛާބެއް ތައްޔާރު ކުރެވިފައިވެއެވެ. 4:93
- ﷲ ގެ މަގުގައި (ޤައުމު) ދޫކޮށް ހިޖުރަ ކުރާ މީހާ ބިމުގައި ގިނަ ދިރިއުޅޭ ތަންތަނާއި ޢީޝާއިން ތަނަވަސްކަން ފެންނާނެއެވެ. 4:100
- ނަމާދުތަކުގައި ވަޤުތު ދަމައިގަންނާށެވެ. 4:103
- އަމާނާތް ދޮގުކުރާ މީހުންނަށް އެހީތެރިއެއް ނުވާށެވެ. އަދި އެއުރެންގެ ވަކީލެއްވެސް ނުވާށެވެ. 4:105
- ﷲ ގެ ޙަޟްރަތުން ފާފަ ފުއްސެވުމަށް އެދޭށެވެ. ހަމަކަށްވަންކަމާއެވެ. ﷲ އީ ގިނަގުނަށް ފުއްސަވާ ރަޙީމްވަންތަ ރަސްކަލާނގެއެވެ. 4:106
- އޭ އީމާންވެއްޖެ މީސްތަކުންނޭވެ. ޢަދުލުވެރިކަމުގައި ސާބިތުވެ ތިބޭށެވެ. ﷲ އަށް ހެކިވެރިންކަމުގައެވެ. އެއީ ތިޔަބައިމީހުންގެ އަމިއްލަ ނަފްސުތަކާއި މައިންބަފައިންނާއި ގާތްތިމާގެ މީހުންގެ މައްޗަށް ވިޔަސް މެއެވެ. އެމީހާ މުއްސަނދިވެސް ނުވަތަ ފަޤީރުވެސް މެއެވެ. ޢަދުލު ލަސް ނުކުރާށެވެ. ނުބައިކަން ރަނގަޅު ކުރުމުގައި އަވަސްވެގަންނާށެވެ. 4:135
- މުނާފިޤުން ﷲ އަށް މަކަރު ހަދަން އުޅެއެވެ. އެހެނެއްކަމަކު އެކަލާނގެ އެއުރެންނަށް މަކަރު ހައްދަވަނީއެވެ. 4:142
- މުނާފިޤުން ނަރަކަމުގެ އެންމެ ފަސް ފަންގިފިލިގައި ވެއްޖެއެވެ. އެއުރެންނަށް އެހީތެރިއެއް ނުފެންނާނެތެވެ. 4:145
- ﷲ އަނިޔާލިބިފައިވާ މީހާ މެނުވީ ފާޅުގައި ނުބައި ބަސް ބުނުމަށް ލޯބި ނުކުރައްވައެވެ. 4:148
- ރަސޫލުންނީ އުފާވެރި ޚަބަރު ދޭ ބޭކަލުންނާއި ބިރުވެރިކަމުގެ ޚަބަރު ދޭ ބޭކަލުންނެވެ. އެއީ ރަސޫލުންނަށްފަހު މީސްތަކުންނަށް ﷲ އާ ދިމާއަށް ޢުޛުރެއް ނުވުމަށްޓަކައެވެ. 4:165
- ތިޔަބައިމީހުންގެ ޢަހުދުތަކާއި ވަޢުދުތައް ފުއްދާށެވެ. 5:1
- ހެޔޮކަމާއި ތަޤުވާގައި އެއްބަޔަކަށް އަނެއްބަޔަކު އެހީތެރިވާށެވެ. ފާފައާއި ޢުދުވާނުގައި ނޫނެވެ. 5:2
- މަރުވެފައިވާ ތަކެތި، އެތަކެއްޗެއްގެ ލޭ، ނުވަތަ އޫރުގެ މަސް ނުކާށެވެ. 5:3
- ޢަދުލުވެރިވާށެވެ. އެހެން މީހުންނަށް އޮތް ޢަދާވަތާއި ރުޅިވެރިކަން ތިޔަބައިމީހުން ޢަދުލުން ދުރުކުރިޔަނުދޭށެވެ. މުޢާމަލާތުގައި ޢަދުލުވެރިވެ އިންޞާފުވެރިވާށެވެ. ޢަދުލުވެރިކަމަކީ ތަޤުވާއާ ގާތް ކަމެއް ކަމުގައި ދަންނާށެވެ. ޢަދުލު ލަސް ނުކުރާށެވެ. ނުބައިކަން ރަނގަޅު ކުރުމުގައި އަވަސްވެގަންނާށެވެ. 5:8
- ﷲ އަށް ގާތްވުމުގެ ވަސީލަތް ހޯދާށެވެ. އަދި އެކަލާނގެ މަގުގައި ކުޅަދާނަވީ ވަރަކުން ޖިހާދު ކުރާށެވެ. އެއީ ތިޔަބައިމީހުން ކާމިޔާބުވުމަށްޓަކައެވެ. 5:35
- ތިޔަބައިމީހުންގެ ޤަސަމާއި ޢަހުދުތައް ފުއްދާށެވެ. 5:89
- މަސްތުވާ ތަކެތިން ދުރުވާށެވެ. މަސްތުވާ ތަކެތި (ހުރިހާ ބާވަތެއްގެ ރާއާއި މަސްތުވާ ތަކެތި)، ޖުވާކުޅުން، އަލްއަންޞާބު (ހިލަ ގުނބުރު)، އަދި އަލްއަޒުލާމް (ނަސީބު ނުވަތަ ނިންމުން ހޯދުމަށް ބޭނުންކުރާ ތީރު) މިއީ ޝައިޠާނާގެ ޢަމަލުތަކުގެ ތެރެއިންވާ ނަޖިސް ކަންތަކެވެ. 5:90
- ޙައްޖު ނުވަތަ ޢުމްރާގެ އިޙްރާމް ޙާލަތުގައި ޝިކާރެއް ނުޤަތުލާށެވެ. 5:95
- ތިޔަބައިމީހުންނަށް ބަޔާންވެއްޖެނަމަ ދަތިކަމަށް މެދުވެރިވާނެ ކަންތަކާ މެދު ސުވާލެއް ނުކުރާށެވެ. 5:101
- އެހެން މީހުންގެ އިލާހުންނަށް ނިކަމެތި ނުކުރާށެވެ. ﷲ ފިޔަވައި އެއުރެން (ކާފިރުން) އަޅުކަން ކުރާ ތަކެތި ނިކަމެތި ނުކުރާށެވެ. އެއުރެން ޢިލްމެއް ނެތި ނާޙައްޤުގޮތުގައި ﷲ އަށް ނިކަމެތި ނުކުރުމަށްޓަކައެވެ. 6:108
- ބިމުގައިވާ ގިނަ މީހުންނަށް ތިޔަބައިމީހުން ކިޔަމަންވެއްޖެނަމަ އެއުރެން ﷲ ގެ މަގުން ތިޔަބައިމީހުން ދުރަށް ފުނގެންދާނެއެވެ. އެއުރެން ތަބަޢަވަނީ ހީކުރުން މެނުވީ ނޫނެވެ. އަދި އެއުރެން ދޮގު މެނުވީ ނުކުރެތެވެ. 6:116
- ފާފަތައް (އޭ މީސްތަކުންނޭވެ. ހުރިހާ ބާވަތެއްގެ) ފާޅުވެގެންވާ އަދި ސިއްރު ފާފަތައް ދޫކޮށްލާށެވެ. 6:120
- ﷲ ގެ ނަންފުޅު ނުގެންނަ (ޛަބީޙަ ކުރާ ވަގުތު) މަސް ނުކާށެވެ. (އޭ މުއުމިނުންނޭވެ.) 6:121
- ﷲ ހިދާޔަތް ދެއްވުމަށް އިރާދަކުރައްވާ މީހާގެ ހިތް އިސްލާމަށް ފުޅާ ކުރައްވައެވެ. އަދި ފުނގެންދަވަން އިރާދަކުރައްވާ މީހާގެ ހިތް ދަތި ކުރައްވައެވެ. 6:125
- ހޭދަކުރުމުގައި މެދުމިންވަރުވާށެވެ. އަދި އިސްރާފުން ދުރުވާށެވެ. ހުރިހާ މަޚްލޫޤުންގެ ޙައްޤުތައް ރައްކާތެރިކުރާށެވެ. 6:141
- ﷲ އަށް އަޅުކަމުގައި އެއްވެސް އެއްޗެއް ޝަރީކު ނުކުރާށެވެ. މައިންބަފައިންނަށް ހެޔޮކަމާއި ކިޔަމަންވުން އަދާ ކުރާށެވެ. ފަޤީރުކަމުގެ ސަބަބުން ދަރިން ނުޤަތުލާށެވެ. ފާޙިޝް ޢަމަލުތަކާ ގާތް ނުވާށެވެ. ﷲ ޙަރާމް ކުރެއްވި ނަފްސެއް ޙައްޤަކާ ނުލައި ނުޤަތުލާށެވެ. 6:151
- ތެދުވެރިވާށެވެ. ތިޔަބައިމީހުންގެ ކޮންމެ މުޢާމަލާތެއްގައި ޚިޔާނާތް ނުކުރާށެވެ. ޔަތީމުންގެ މުދާއަށް ރަނގަޅު ކުރުމަށްޓަކައި މެނުވީ ގާތް ނުވާށެވެ. ޢަދުލުވެރިކަމާއެކު ފުރިހަމަ މިންގަނޑާއި ފުރިހަމަ ބަރުދަން ދޭށެވެ. ތިޔަބައިމީހުން ބަހެއް ބުނާހިނދު ގާތްތިމާގެ މީހެއްގެ ކަމުގައިވިޔަސް ތެދު ބުނާށެވެ. އަދި ﷲ ގެ ޢަހުދު ފުއްދާށެވެ. 6:152
- ސީދާ މަގަށް ތަބަޢަވާށެވެ. އަދި (އެހެން) މަގުތަކަށް ތަބަޢަ ނުވާށެވެ. ފަހެ އެ މަގުތައް އެކަލާނގެ މަގުން ތިޔަބައިމީހުން ވަކި ކުރާނެއެވެ. 6:153
- ކަލޭގެފާނު (މުޙައްމަދު ﷺ) ވިދާޅުވާށެވެ. "ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނުގެ ނަމާދާއި ޤުރުބާނާއި ދިރިހުރުމާއި މަރުވުން ޢާލަމްތަކުގެ ވެރި ﷲ އަށް މިލްކުވެއެވެ." 6:162
- ކިބުރުވެރި ނުވާށެވެ. 7:13
- ޝައިޠާނާ (ފިތުނަވެރިޔާ) ތިޔަބައިމީހުން ނުހެއްޗެއް ނުކުރާށެވެ. 7:27
- ކަލޭގެފާނު (މުޙައްމަދު ﷺ) ވިދާޅުވާށެވެ. "ތިމަންކަލޭގެފާނުގެ ވެރިރަސްކަލާނގެ ޢަދުލަށް އަމުރު ކުރައްވައިފިއެވެ…" 7:29
- ހުރިހާ ކަމެއްގައި ﷲ ކަނޑައެޅުއްވި ޙައްދުތައް ދަމައިގަންނާށެވެ. ބަހުންނާއި ޢަމަލުން ޙައްދު ފަހަނަޅައިނުގޮސް ދުރުވާށެވެ. ކައި ބޯށެވެ. އެހެނެއްކަމަކު އިސްރާފެއް ނުކުރާށެވެ. ނަމާދުކުރާ ވަގުތުތަކުގައި ރީތި ފޭރާން ލާށެވެ. 7:31
- ﷲ އުޑުތަކާއި ބިން ހަ ދުވަހުގެ ތެރޭގައި ޚަލްޤު ކުރެއްވިއެވެ. ދެން އެކަލާނގެ ޢަރްޝްގެ މައްޗަށް އިސްތިވާ ކުރެއްވިއެވެ. (އެކަލާނގެ މަތިވެރިކަމަށް އެކަށީގެންވާ ގޮތަކުންނެވެ.) 7:54
- ތިޔަބައިމީހުންގެ ވެރިރަސްކަލާނގެއަށް އިޚްލާޞްތެރިކަމާއި އޮޅުވައިނުލާ ޙާލު ދަންނަވާށެވެ. އެކަލާނގެ ޙައްދު ފަހަނަޅައިގޮސްފައިވާ މީހުންނަށް ލޯބި ނުކުރައްވައެވެ. 7:55
- ބިމުގައި ރަނގަޅު ގޮތުގައި އައްސަވައިފައިވާ ޙާލު ފަސާދަ ނުކުރާށެވެ. އަދި ބިރުވެތިކަމާއި އުންމީދާއެކު އެކަލާނގެއަށް ދަންނަވާށެވެ. 7:56
- އެހެނެއްކަމަކު ނުބައި ޢަމަލުތައް ކޮށް ދެން އެއަށްފަހު ތައުބާވެ އީމާންވި މީހުން ދަންނާށެވެ. ހަމަކަށްވަންކަމާއެވެ. އެއަށްފަހު ތިބާގެ ވެރިރަސްކަލާނގެ ހަމަކަށްވަންކަމާއެވެ. ގިނަގުނަށް ފުއްސަވާ ރަޙީމްވަންތަ ރަސްކަލާނގެއެވެ. 7:153
- ކަލޭގެފާނު (މުޙައްމަދު ﷺ) ވިދާޅުވާށެވެ. "އޭ މީސްތަކުންނޭވެ. ހަމަކަށްވަންކަމާއެވެ. ތިމަންކަލޭގެފާނު ތިޔަބައިމީހުން ހުރިހާ ބަޔަކަށް ﷲ ގެ ރަސޫލަކު ކަމުގައި ފޮނުއްވައިފިއެވެ…" 7:158
- އަދި އެންމެ ރީތި ނަންފުޅުތައް ﷲ އަށް މިލްކުވެއެވެ. ފަހެ އެ ނަންފުޅުތަކުން އެކަލާނގެއަށް ދަންނަވާށެވެ. އަދި އެކަލާނގެ ނަންފުޅުތަކާ ދެކޮޅު ހަދާ ނުވަތަ ދޮގުކުރާ (ނުވަތަ ނަންފުޅުތަކާ މެދު ނާޖާއިޒު ބަސް ބުނާ) މީހުންގެ އެކުވެރިކަން ދޫކޮށްލާށެވެ… 7:180
- ﷲ ފުނގެންދަވާ މީހަކަށް އެއްވެސް ފަރާތަކުން ހިދާޔަތެއް ނުދެވޭނެއެވެ. އަދި އެއުރެން އެއުރެންގެ ޙައްދު ފަހަނަޅައިގޮތުގައި ބުއްދިނަގަނޑުގައި ދޫކޮށްލައެވެ. 7:186
- ޢަފޫ ކުރާށެވެ. ހެޔޮކަމަށް އަމުރު ކުރާށެވެ. އަދި ޖާހިލުންނާ އެއްކިބާވެގަންނާށެވެ. (އެބަހީ: އެއުރެންނަށް ޢަޛާބެއް ނުދޭށެވެ.) 7:199
- އެހެން މީހުންގެ ކުށްތައް ފުއްސާށެވެ. 7:199
- އަދި ޝައިޠާނާ (ފިތުނަވެރިޔާ) ގެ ކިބައިން ނުބައި ވަސްވާސެއް އައިސްފިނަމަ ﷲ ގެ ޙަޟްރަތުން ޙިމާޔަތް އެދޭށެވެ. ހަމަކަށްވަންކަމާއެވެ. އެކަލާނގެއީ އަޑުއިވެވޮޑިގެންވާ ދެނެވޮޑިގެންވާ ރަސްކަލާނގެއެވެ. 7:200
- މުއުމިނުންނީ ހަމައެކަނި ﷲ ހަނދުމަ ކުރެވޭހިނދު އެއުރެންގެ ހިތްތައް ބިރުވެތިވާ މީހުންނެވެ. އަދި އެކަލާނގެ އާޔަތްތައް އެއުރެންނަށް ކިޔައިދެއްވާހިނދު (އެބަހީ: އެ އާޔަތްތައް) އެއުރެންގެ އީމާންކަން އިތުރު ކުރެއެވެ… 8:2
- ﷲ އަށާއި އެކަލާނގެ ރަސޫލާއަށް ޚިޔާނާތް ނުކުރާށެވެ. އަދި ތިޔަބައިމީހުންނަށް ޙަވާލުކުރެވިފައިވާ އަމާނާތްތަކާއި ﷲ ތިޔަބައިމީހުންގެ މައްޗަށް ފަރްޟު ކުރެއްވި ހުރިހާ ވާޖިބުތަކަށް ދެނެގެން ޚިޔާނާތް ނުކުރާށެވެ. 8:27
- ތިޔަބައިމީހުން ﷲ އަށް ކިޔަމަންވެ އެކަލާނގެއަށް ބިރުވެތިވެއްޖެނަމަ އެކަލާނގެ ތިޔަބައިމީހުންނަށް ފުރުޤާން (ޙައްޤާއި ބާޠިލް ވަކިކުރުމަށް ނިންމާ މިންގަނޑެއް) ދެއްވާނެއެވެ. (ނުވަތަ ކޮންމެ ދަތިކަމަކުން ނިކުތުމުގެ މަގެއް ދެއްވާނެއެވެ.) 8:29
- ކާފިރުވި މީހުން އެއުރެންގެ މުދާ ހޭދަ ކުރަނީ ﷲ ގެ މަގުން (މީސްތަކުން) ދުރު ކުރުމަށެވެ. ފަހެ އެއުރެން އެ ހޭދަ ކުރުން ކުރިއަށް ގެންދާނެއެވެ. އެހެނެއްކަމަކު ނިމުންގައި އެއީ އެއުރެންނަށް ހިތާމައަކަށް ވެގެންދާނެއެވެ. 8:36
- ކާފިރުވި މީހުންނަށް ބުނާށެވެ. އެއުރެން (ކުފުރުން) ހުއްޓައިފިނަމަ އެއުރެންގެ ކުރީގެ (ފާފަތައް) ފުއްސެވޭނެއެވެ. އެހެނެއްކަމަކު އެއުރެން (އެކަމަށް) އަނބުރާ އައިފިނަމަ ފަހެ އެއުރެންގެ ކުރިން ތިބި (ޢަޛާބު ލިބުނު) މީހުންގެ މިސާލުތައް ވަނީ ފާއިތުވެގެންނެވެ. (އިންޛާރެއްގެ ގޮތުގައެވެ.) 8:38
- ތިޔަބައިމީހުން (ޢަދުއްވެއްގެ) ލަޝްކަރަކާ ބައްދަލުވާހިނދު ސާބިތުވެ ތިބޭށެވެ. އަދި ﷲ ގެ ނަންފުޅު ގިނަގިނައިން ހަނދުމަ ކުރާށެވެ. (ދުލާއި ހިތުންނެވެ.) އެއީ ތިޔަބައިމީހުން ކާމިޔާބުވުމަށްޓަކައެވެ. 8:45
- އެއުރެންގެ ގެތަކުން ފަޚުރުވެރިކަމާއި މީސްތަކުންނަށް ފެންނަން ނިކުންނަ އަދި ﷲ ގެ މަގުން (މީސްތަކުން) ދުރުކުރާ މީހުން ފަދައިން ނުވާށެވެ. 8:47
- ﷲ އެއްވެސް ޤައުމަކަށް ދެއްވި ނިޢުމަތެއް އެއުރެން އެއުރެންގެ އަމިއްލަ ނަފްސުތަކުގައިވާ ކަންތައް ބަދަލު ނުކުރައްވާ ހައްދަން ނުބަދަލު ކުރައްވައެވެ. 8:53
- ﷲ ގެ ޙަޟްރަތުގައި ދިރޭ މަޚްލޫޤުންގެ ތެރެއިން އެންމެ ނުބައި މަޚްލޫޤުންނީ ކާފިރުވި މީހުންނެވެ. 8:55
- ﷲ އެކަލާނގެއަށް އީމާންވާ މީހުންގެ ހިތްތަކުގެ މެދުގައި ލޯބިއާއި އޯގާތެރިކަން ލައްވައެވެ. 8:63
- ޙިމާޔަތް އެދޭ މީހުންނަށް ޙިމާޔަތް ދީ އެހީތެރިވާށެވެ. 9:6
- ﷲ ގެ މަސްޖިދުތައް ބަލަހައްޓަން މުޝްރިކުންނަށް ޙައްޤެއް ނުވެއެވެ. 9:17
- އެއުރެން (ކާފިރުން، ޔަހޫދީންނާއި ނަޞާރާއިން) ބޭނުންވަނީ އެއުރެންގެ އަނގަތަކުން ﷲ ގެ ނޫރު (މުޙައްމަދު ﷺ ފޮނުއްވައިގެން އައި އިސްލާމީ ތައުޙީދު) ނިއްވާލުމަށެވެ. އެހެނެއްކަމަކު ﷲ އެކަލާނގެ ނޫރު ފުރިހަމަ ކުރެއްވުން މެނުވީ ދޫކުރައްވައެއް ނުދެއްވާނެއެވެ. ކާފިރުން އެކަމަށް ނުރުހުނަސްމެއެވެ. 9:32
- ޞަދަޤާތުތައް (އެބަހީ: ޒަކާތް) މިލްކުވަނީ 1) ފުޤަރާއުން (ފަޤީރުން)، 2) މަސާކީނުން (ފަޤީރުން)، 3) ޒަކާތުގެ މުދާ އަދާ ކުރުމަށް ޢައްޔަން ކުރެވިފައިވާ މީހުން، 4) އިސްލާމް ދީނަށް ލޯބި ޖެއްސުމަށްޓަކައި، 5) އަޅުން މިނިވަން ކުރުމަށް، 6) ދަރިމަދުވެރިންނަށް، 7) ﷲ ގެ މަގުގައި (އެބަހީ: މުޖާހިދުންނަށް)، އަދި 8) ދަތުރުވެރިންނަށެވެ. 9:60
- ﷲ އަށާއި އެކަލާނގެ ރަސޫލާ (ﷺ) އަށް ދެކޮޅުހަދައި ޢަދާވަތް ދައްކާ މީހާ ދަންނާށެވެ. ހަމަކަށްވަންކަމާއެވެ. އޭނާއަށް ނަރަކަމުގެ އަލިފާން ވެއެވެ. އެތާނގައި އަބަދަށް ދެމިތިބޭ ޙާލުއެވެ. އެއީ ބޮޑުވެގެންވާ ނިކަމެތިކަމެވެ. 9:63
- މުނާފިޤުން، ފިރިހެނުންނާއި އަންހެނުން އެއްބަޔަކު އަނެއްބަޔަކުންނެވެ. އެއުރެން ﷲ ހަނދުމަ ނުކުރިއެވެ. ފަހެ އެކަލާނގެވެސް އެއުރެން ހަނދުމަ ނުކުރެއްވިއެވެ. 9:67
- ޠާހިރުކަމަށް މަސައްކަތް ކުރާށެވެ. މަސްޖިދުގެ ޙުރުމަތް ޤަދަރު ކުރާށެވެ. 9:108
- ނަބިއްޔާއަށާއި އީމާންވި މީހުންނަށް މުޝްރިކުންނަށް ﷲ ގެ ޙަޟްރަތުން ފާފަ ފުއްސެވުމަށް އެދުން ޙައްޤެއް ނުވެއެވެ. އެއުރެން ގާތްތިމާގެ މީހުން ކަމުގައިވިޔަސްމެއެވެ. އެއުރެން ނަރަކަމުގެ އަހުލުވެރިން ކަމަށް (އެބަހީ: ކުފުރުގެ ޙާލުގައި މަރުވެގެން) ބަޔާންވެއްޖެހިނދުއެވެ. 9:113
- ﷲ އާ ދިމާއަށް ދޮގެއް އުފައްދައި ނުވަތަ އެކަލާނގެ އާޔަތްތައް ދޮގުކޮށްފި މީހަކަށްވުރެ ބޮޑަށް އަނިޔާވެރިވެގެންވާ މީހަކު ނުވެތެރެވެ. ހަމަކަށްވަންކަމާއެވެ. ކުށްވެރިން ނާކާމިޔާބުވާނެއެވެ! 10:17
- އެއުރެން ﷲ ފިޔަވައި އެއުރެންނަށް ގެއްލުމެއް ނުދޭ އަދި މަންފާއެއްވެސް ނުކުރާ ތަކެތިއަށް އަޅުކަން ކުރެތެވެ. އަދި އެއުރެން ބުނެތެވެ. "މިއީ ﷲ ގެ ޙަޟްރަތުގައި ތިމަންމެންނަށް ޝަފާޢަތް ކޮށްދޭނެ ފަރާތްތަކެވެ." ކަލޭގެފާނު ވިދާޅުވާށެވެ. "އުޑުތަކާއި ބިމުގައި އެކަލާނގެ ނުދެނެވޮޑިގަންނަވާ ކަންތަކެއް ﷲ އަށް އަންގަނީތޯއެވެ؟" އެއުރެން އެކަލާނގެއަށް ޝަރީކު ކުރާ ހުރިހާ ތަކެއްޗަށްވުރެ އެކަލާނގެ މަތިވެރިވެ މާތްވެގެންވެއެވެ! 10:18
- ނުބައި ޢަމަލެއްގެ ޖަޒާއަކީ އެ ޢަމަލާ އެއްފަދަ އެއްޗެކެވެ. 10:27
- އެކަލާނގެއީ ﷲ އެވެ. ތިޔަބައިމީހުންގެ ވެރި ޙައްޤު ރަސްކަލާނގެއެވެ. ފަހެ ޙައްޤަށްފަހު މަގުފުރެދުން މެނުވީ އެއްވެސް އެއްޗެއް ނެތެވެ. ފަހެ ތިޔަބައިމީހުން އެނބުރިދަނީ ކިހިނަކުންތޯއެވެ؟ 10:32
- އެއުރެންގެ ގިނަބަޔަކު ހީކުރުން މެނުވީ ތަބަޢައެއް ނުވެތެވެ. ހަމަކަށްވަންކަމާއެވެ. ހީކުރުމަކީ ޙައްޤާ ދެކޮޅަށް އެއްވެސް ކަމެއް ފުއްދައިދޭނެ އެއްޗެއް ނޫނެވެ. 10:36
- ހަމަކަށްވަންކަމާއެވެ! ﷲ މީސްތަކުންނަށް އެއްވެސް ކަމެއްގައި އަނިޔާއެއް ނުކުރައްވައެވެ. އެހެނެއްކަމަކު މީސްތަކުން އެއުރެންގެ އަމިއްލަ ނަފްސުތަކަށް އަނިޔާ ކުރެތެވެ. 10:44
- ދަންނާށެވެ. ﷲ ގެ ފަޟްލު ވެރިކަން އިންސާނާ ޖަމާކޮށް ރައްކާކުރާ ކޮންމެ އެއްޗަކަށްވުރެ މާތެވެ. 10:58
- ﷲ ގެ އާޔަތްތައް ދޮގުކުރާ މީހުންގެ ތެރެއިން ނުވާށެވެ. ފަހެ އެހިނދު ތިޔަބައިމީހުން ގެއްލުންވެރިންގެ ތެރެއިން ވެދާނެއެވެ. 10:95
- ﷲ ތިބާއަށް ދަތިކަމެއް ޖެއްސެވިނަމަ އެކަލާނގެ މެނުވީ އެ ދަތިކަން ނައްތާލަން އެއްވެސް ފަރާތެއް ނުވެއެވެ. އަދި އެކަލާނގެ ތިބާއަށް ހެޔޮކަމެއް އިރާދަކުރައްވައިފިނަމަ އެކަލާނގެ އެކަލާނގެ އަޅުތަކުންގެ ތެރެއިން އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށް ދެއްވާ ފަޟްލު ވެރިކަން ރައްދު ކުރައްވަން އެއްވެސް ފަރާތެއް ނުވެއެވެ. 10:107
- ބިމުގައި ހިނގާ ކޮންމެ ދިރޭ މަޚްލޫޤެއްގެ ރިޒްޤު ﷲ ގެ މައްޗަށް ވެއެވެ. އަދި އެކަލާނގެ އެ މަޚްލޫޤު އުޅޭ ތަނާއި އެ މަޚްލޫޤު ރައްކާކުރެވޭ ތަން (ރަޙިމުގައްޔާއި ޤަބުރުގައި ފަދަތަންތަން) ދެނެވޮޑިގެންވެއެވެ. 11:6
- ތިމަންރަސްކަލާނގެ ޙަޟްރަތުން އިންސާނާއަށް ރަޙްމަތެއްގެ ރަހަ ދައްކައި ދެން އެކަން އޭނާގެ ކިބައިން ނަގައިފިނަމަ ހަމަކަށްވަންކަމާއެވެ! އޭނާ އުންމީދު ކެނޑިފައިވާ ޝުކުރު ނުކުރާ މީހަކު ކަމުގައި ވެއެވެ. 11:9
- ދުނިޔޭގެ ދިރިއުޅުމާއި އޭގެ ޒީނަތް ބޭނުންވާ މީހުންނަށް ތިމަންރަސްކަލާނގެ އެތާނގައި އެއުރެންގެ ޢަމަލުތަކުގެ (އުޖޫރަ) ފުރިހަމައަށް ދެއްވާނަމެވެ. އަދި އެތާނގައި އެއުރެންނަށް އެއްވެސް އުނިކަމެއް ނުކުރައްވާނެއެވެ. 11:15
- ތިމަންރަސްކަލާނގެ އެއުރެންނަށް އަނިޔާއެއް ނުކުރައްވަމެވެ. އެހެނެއްކަމަކު އެއުރެން އެއުރެންގެ އަމިއްލަ ނަފްސުތަކަށް އަނިޔާ ކުރޫއެވެ. ފަހެ ތިބާގެ ވެރިރަސްކަލާނގެ އަމުރުފުޅު އައިހިނދު އެއުރެން އަޅުކަން ކުރި އެކަލާނގެ ފިޔަވައިވާ އެއުރެންގެ އިލާހުން އެއުރެންނަށް އެއްވެސް މަންފާއެއް ނުކުރިއެވެ. އަދި ނަސްދައުމެއް މެނުވީ އެއުރެންގެ ޙައްޤުގައި އެއުރެން އިތުރެއް ނުކުރިއެވެ. 11:101
- އެ ދުވަސް އައިހިނދު ﷲ ގެ އިޛުނަފުޅާ ނުލައި އެއްވެސް މީހަކު ވާހަކައެއް ނުދައްކާނެއެވެ. ފަހެ އެއުރެންގެ ތެރެއިން ބައެއް މީހުންނީ ދަތިންނާއި އަނެއްބައި މީހުންނީ އުފާވެރިންނެވެ. 11:105
- ދަތިންނާ މެދުވެރިވި މީހުން ދަންނާށެވެ. އެއުރެން ނަރަކަމުގައި އުޅޭނެއެވެ. އުސް އަޑާއި ތިރި އަޑުން ނޭވާ ލަމުންނެވެ. 11:106
- އުޑުތަކާއި ބިން ދެމިއޮތް ހައިރު އެތާނގައި އެއުރެން ދެމިތިބޭނެއެވެ. ތިބާގެ ވެރިރަސްކަލާނގެ އިރާދަކުރެއްވި ކަމަކީ މެނުވީއެވެ. ހަމަކަށްވަންކަމާއެވެ. ތިބާގެ ވެރިރަސްކަލާނގެ އިރާދަކުރައްވާ ކަންތައް ކުރައްވާ ރަސްކަލާނގެއެވެ. 11:107
- އަދި އުފާވެރިވި މީހުން ދަންނާށެވެ. އެއުރެން ސުވަރުގޭގައި އުޅޭނެއެވެ. އުޑުތަކާއި ބިން ދެމިއޮތް ހައިރު އެތާނގައި އެއުރެން ދެމިތިބޭނެއެވެ. ތިބާގެ ވެރިރަސްކަލާނގެ އިރާދަކުރެއްވި ކަމަކީ މެނުވީއެވެ. ނިމުމެއް ނެތް ހަދިޔާއެކެވެ. 11:108
- އަނިޔާވެރިވި މީހުންނަށް ލޯބި ނުކުރާށެވެ. އެހިނދު ނަރަކަމުގެ އަލިފާން ތިޔަބައިމީހުންނަށް ބީހިދާނެއެވެ. އަދި ﷲ ފިޔަވައި ތިޔަބައިމީހުންނަށް އެއްވެސް ރައްކާތެރިޔަކު ނުވެއެވެ. އަދި އެހިނދު ތިޔަބައިމީހުންނަށް އެހީއެއްވެސް ނުލިބޭނެއެވެ. 11:113
- ދުވާހުގެ ދެ ކޮޅުގައްޔާއި ރޭގަނޑުގެ ބައެއް ގަޑިއިރުތަކުގައި ނަމާދު ޤާއިމު ކުރާށެވެ. (އެބަހީ: ދުވާލު ފަސް ނަމާދެވެ.) ހެޔޮ ޢަމަލުތައް ނުބައި ޢަމަލުތައް ފޮހެލައެވެ. (އެބަހީ: ކުދި ފާފަތަކެވެ.) 11:114
- އުޑުތަކާއި ބިމުގެ ޣައިބު ﷲ އަށް މިލްކުވެއެވެ. އަދި ހުރިހާ ކަމެއް (ނިންމެވުމަށް) އެކަލާނގެ ޙަޟްރަތަށް ރައްދުވެއެވެ. 11:123
- ޙުކުމް (ނުވަތަ ނިޔާ) އޮތީ ﷲ އަށް މެނުވީ އެއްވެސް ފަރާތަކަށް ނޫނެވެ. އެކަލާނގެ އަމުރު ކުރައްވައިފިއެވެ. ތިޔަބައިމީހުން އެކަލާނގެ މެނުވީ އެއްވެސް ފަރާތަކަށް އަޅުކަން ނުކުރުމަށެވެ. (އެބަހީ: އެކަލާނގެ އެއްކައުވަންތަކަމަށެވެ.) އެއީ (ޙައްޤު) ސީދާ ދީނެވެ. އެހެނެއްކަމަކު މީސްތަކުންގެ ގިނަބަޔަކު ނުދަނެތެވެ. 12:40
- ﷲ ގެ ރަޙްމަތުން އުންމީދު ކެނޑިނުދާށެވެ. 12:87
- ތިބާ ބޮޑަށް އެދިވެސް މީސްތަކުންގެ ގިނަބަޔަކު އީމާނެއް ނުވާނެތެވެ. 12:103
- އަދި އެއުރެންގެ ގިނަބަޔަކު ﷲ އަށް އީމާނެއް ނުވެތެވެ. އެހެނެއްކަމަކު އެއުރެން އެކަލާނގެއަށް ބައިވެރިން ލައެވެ. (އެބަހީ: އެއުރެންނީ މުޝްރިކުންނެވެ.) 12:106
- އެ (ޤުރުއާން) އީ އުފައްދައިފައިވާ ބަހެއް ނޫނެވެ. އެހެނެއްކަމަކު އެއީ ﷲ ގެ ޙަޟްރަތުން ބާޣުކުރެއްވި ފޮތްތައް (ތައުރާތާއި އިންޖީލާއި ﷲ ގެ އެހެން ފޮތްތައް) ތަޞްދީޤު ކުރުމެކެވެ. އަދި ކޮންމެ ކަމެއް ތަފްޞީލުކޮށް ބަޔާން ކުރުމެކެވެ. އަދި އީމާންވާ މީސްތަކުންނަށް ހިދާޔަތަކާއި ރަޙްމަތެކެވެ. 12:111
- ﷲ އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށް ރިޒްޤު އިތުރު ކުރައްވައެވެ. އަދި (އެކަލާނގެ އިރާދަކުރައްވާ މީހަކަށް) ދަތި ކުރައްވައެވެ. 13:26
- ޛިކުރުން ﷲ ގިނަގިނައިން ހަނދުމަ ކުރާށެވެ. ﷲ އަށް އީމާންވާ މީހުން އެކަލާނގެ ހަނދުމަ ކުރުމުން ހިތްހަމަޖެހުން ލިބިގަނެއެވެ. 13:28
- އީމާންވެ ހެޔޮ ޢަމަލު ކުޅަ މީހުންނަށް އުފާއާއި ހިތްހަމަޖެހުން ލިބެއެވެ. 13:29
- އާޚިރަތުގެ ބަދަލުގައި ދުނިޔޭގެ ދިރިއުޅުން އިސްކޮށްފި މީހުންނާއި ﷲ ގެ މަގުން (އެބަހީ: އިސްލާމް ދީނުން) މީސްތަކުން ދުރުކޮށް އެ މަގުގައި ގުދަންކަން އިރާދަކުރި މީހުންނީ ދުރުވެގެންވާ މަގުފުރެދުމެއްގައިވާ މީހުންނެވެ. 14:3
- އަޅުކަމުގައި އިންތިހާއަށް ދާ ނަމާދާއި ޝުކުރު އާދަ ކުރާށެވެ. 14:7
- އެއުރެންގެ ވެރިރަސްކަލާނގެއަށް ކާފިރުވި މީހުންގެ މިސާލަކީ އެއުރެންގެ ޢަމަލުތައް ކަހަލައެވެ. އެއީ ވައިގަދަ ދުވަހެއްގައި ވައި ބާރުމިން އުދުއްސާލާ ކަހަލައެވެ. އެއުރެން ހޯދި ކަންތަކުން އެއްވެސް އެއްޗެއް އެއުރެންނަކަށް ނުލިބޭނެތެވެ. 14:18
- ﷲ އީމާންވި މީހުން ދުނިޔޭގައި (އެބަހީ: އެއުރެން ހަމައެކަނި ﷲ އަށް އަޅުކަން ކުރުން ދެމިއަހައްޓާނެއެވެ.) އަދި އާޚިރަތުގައިވެސް ސާބިތުކޮށް ބަހައްޓަވާނެއެވެ. 14:27
- އަނިޔާވެރިން (މުޝްރިކުންނާއި ނުބައިކަންކުރާ މީހުން ފަދަ މީހުން) ކުރާ ކަންތަކާ މެދު ﷲ ޣާފިލުވެވޮޑިގެންވެއެވެ ނުދަންނަވާށެވެ. އެހެނެއްކަމަކު އެކަލާނގެ އެއުރެންނަށް މުހުލަތް ދެއްވަނީ ލޯތައް ބިރުވެތިކަމުން ބަލަން ޖެހޭ ދުވަހަކާ ހަމަޔަށެވެ. 14:42
- އެއީ ﷲ ކޮންމެ މީހަކަށްވެސް އެމީހާ ހޯދި ކަންތަކަށް ޖަޒާ ދެއްވުމަށްޓަކައެވެ. ހަމަކަށްވަންކަމާއެވެ. ﷲ އީ ޙިސާބު ކުރުމުގައި އަވަސްވެވޮޑިގެންވާ ރަސްކަލާނގެއެވެ. 14:51
- އަދި ހަމަކަށްވަންކަމާއެވެ. ތިމަންރަސްކަލާނގެ އިންސާނާ ޚަލްޤު ކުރެއްވީ ވަރަށް ދޮންނަ ކަޅު މަށީގެ ތެރެއިން އަޑު އިވޭ މަށިކައްޗަކުންނެވެ. 15:26
- އަދި ޖިންނީން ތިމަންރަސްކަލާނގެ ކުރިން ދުންނެތް އަލިފާނުގެ ލާފަލުން ޚަލްޤު ކުރެއްވީމެވެ. 15:27
- އެ (ނަރަކަމު) އަށް ހަތް ދޮރު ވެއެވެ. އެ ދޮރުތަކުގެ ކޮންމެ ދޮރަކަށްވެސް (ފާފަވެރިންގެ) ޚާއްޞަ ބަޔެއް ކަނޑައެޅިފައިވެއެވެ. 15:44
- އެކަލާނގެ އިންސާނާ ޚަލްޤު ކުރެއްވީ ނުތުފާ (ފިރިހެނާއާއި އަންހެނާގެ ޖިންސީ ދަރިފަޅައިގެ ބައިތަކުގެ މަށި) އިންނެވެ. ދެން އެހެން ނުވެދާށެވެ. މި އަމިއްލަ (އިންސާނާ) ފާޅުވެގެންވާ ދެކޮޅުވެރިޔަކަށް ވެއެވެ. 16:4
- އަދި ޖަނަވާރުތައް އެކަލާނގެ ތިޔަބައިމީހުންނަށް ޚަލްޤު ކުރެއްވިއެވެ. އެތަކެތީގައި ހަރުގަނޑާއި ގިނަ މަންފާތައް ވެއެވެ. އަދި އެއިން ތިޔަބައިމީހުން ކައެވެ. 16:5
- އަދި (އެކަލާނގެ ޚަލްޤު ކުރެއްވި) އަސްތަކާއި ބައްތަކާއި ހިމަރުތައް ތިޔަބައިމީހުން އެއަށް އަރައި ދަތުރުކުރުމަށާއި ޒީނަތެއްގެ ގޮތުގައެވެ. އަދި ތިޔަބައިމީހުންނަށް ނޭނގޭ އެހެން ތަކެތިވެސް އެކަލާނގެ ޚަލްޤު ކުރައްވައެވެ. 16:8
- އެކަލާނގެއީ އުޑުން ފެން (ވާރޭ) ބާޣުކުރައްވާ ރަސްކަލާނގެއެވެ. އެއިން ތިޔަބައިމީހުން ބޮއެއެވެ. އަދި އެއިން (ފެޅިގެން) ތިޔަބައިމީހުންގެ ޖަނަވާރުތައް ރައްކާކުރާ ބިންގަސްތައް ފެޅެއެވެ. 16:10
- އެކަލާނގެއީ ތިޔަބައިމީހުންނަށް ކަނޑު ބަންނަވައި ދެއްވި ރަސްކަލާނގެއެވެ. އެއިން ތިޔަބައިމީހުން ފެންނަ މަސް ކައެވެ. (އެބަހީ: މަސްމަހާމެއްޔެވެ.) އަދި އެއިން ތިޔަބައިމީހުން އަޅާ ޒީނަތްތައް ނެރެއެވެ. 16:14
- އެކަލާނގެ ބިމުގައި ސާބިތުވެގެންވާ ފަރުބަދަތައް އެޅުއްވިއެވެ. އެއީ ތިޔަބައިމީހުންނާއެކު އެ ބިން ހަލުވިދާނެ ކަމަށްޓަކައެވެ. އަދި ކޯރުތަކާއި މަގުތައްވެސްމެއެވެ. އެއީ ތިޔަބައިމީހުން މަގު ދެނެގަތުމަށްޓަކައެވެ. 16:15
- ފަހެ ޚަލްޤު ކުރައްވާ ރަސްކަލާނގެ ޚަލްޤު ނުކުރައްވާ ފަދަ މީހަކާ އެއްފަދަވާނީތޯއެވެ؟ ފަހެ ތިޔަބައިމީހުން ހަނދާން ނުކުރަނީހެއްޔެވެ؟ 16:17
- ތިޔަބައިމީހުން ﷲ ގެ ނިޢުމަތްތައް އަދަދު ކުރަން އުޅުނަސް އެ ނިޢުމަތްތައް އަދަދު ނުކުރެވޭނެއެވެ. 16:18
- ﷲ ތިޔަބައިމީހުން ސިއްރުކޮށްފައިވާ ކަންތަކާއި ފާޅުކޮށްފައިވާ ކަންތައް ދެނެވޮޑިގެންވެއެވެ. 16:19
- އެއުރެން (މުޝްރިކުން) ﷲ ފިޔަވައި އަޅުކަން ކުރާ ތަކެތި އެއްވެސް އެއްޗެއް ނުޚަލްޤު ކުރެތެވެ. އެހެނެއްކަމަކު އެއުރެންނީ ޚަލްޤު ކުރެވިފައިވާ ތަކެތިއެވެ. 16:20
- (އެއުރެންނީ) މަރުވެފައިވާ ދިރުމެއް ނެތް ތަކެތިއެވެ. އަދި އެއުރެން ދިރުއްވެވޭނީ ކޮންއިރަކުންކަންވެސް ނުދަނެތެވެ. 16:21
- ތިމަންރަސްކަލާނގެ ކަމަކަށް އިރާދަކުރައްވައިފިނަމަ އެކަމަކަށް ވިދާޅުވަނީ ހަމައެކަނި "ވާށެވެ!" މިފަދައިންނެވެ. ފަހެ އެއީ ވެގެންދެއެވެ. 16:40
- ފަހެ ނުބައި ރޭވުންތައް ރޭވާ މީހުން ﷲ އެއުރެން ބިމުގައި ޣާރިޤު ނުކުރައްވާނެ ކަމަށް ނުވަތަ އެއުރެން ނުދެނޭ ދިމަދިމާއިން ޢަޛާބު އައިސް ނުޖެހޭނެ ކަމަށް އަމާންވެގެން ތިބޭނީހެއްޔެވެ؟ 16:45
- ތިޔަބައިމީހުންނަށް ލިބިފައިވާ ކޮންމެ ނިޢުމަތަކާއި ހެޔޮ ތަކެއްޗެއް ﷲ ގެ ޙަޟްރަތުންނެވެ. ދެން ތިޔަބައިމީހުންނަށް ދަތިކަމެއް ޖެހިއްޖެނަމަ އެކަލާނގެ ޙަޟްރަތަށް އަޑުއުސްކޮށް އެހީއަށް ގޮވައެވެ. 16:53
- ދެން އެކަލާނގެ ތިޔަބައިމީހުންގެ ކިބައިން އެ ދަތިކަން ނައްތާލެއްވުމުން އޭ އަޖާއިބެވެ! ތިޔަބައިމީހުންގެ ތެރެއިން ބައެއް މީހުން އެއުރެންގެ ވެރިރަސްކަލާނގެއަށް ބައިވެރިން ލަތެވެ. 16:54
- ޖަނަވާރުތަކުގައި ތިޔަބައިމީހުންނަށް ޢިބްރަތެއް ވެއެވެ. ނަޖިސާއި ލޭގެ މެދުން ޠާހިރު ކިރެއް ތިމަންރަސްކަލާނގެ އެއުރެންގެ ބަނޑުތަކުން ތިޔަބައިމީހުންނަށް ބޯން ދެއްވަމެވެ. ބޯންޏަށް މީރުވެގެންވެއެވެ. 16:66
- ފަހެ ﷲ އަށް މިސާލު ނުޖައްސާށެވެ. (އެކަލާނގެއާ އެއްފަދަ އެއްވެސް އެއްޗެއް ނެތެއެވެ. އަދި އެކަލާނގެ އެއްވެސް އެއްޗަކާ އެއްފަދަވެވޮޑިގެންނެއް ނުވެއެވެ.) ހަމަކަށްވަންކަމާއެވެ! ﷲ ދެނެވޮޑިގެންވެއެވެ. އަދި ތިޔަބައިމީހުން ނުދަނެތެވެ. 16:74
- ދަންނާށެވެ. ﷲ އިންސާނާއަށް އިވުމާއި ފެނުމާއި ބުއްދިއާއި ހިތްތައް ދެއްވީ އެއުރެން ޝުކުރު ކުރުމަށްޓަކައެވެ. 16:78
- ދަހިވެތިކަމާއި ތަމަހައި ކުރުމުން ދުރުވާށެވެ. 16:97
- ތިޔަބައިމީހުން ޤުރުއާން ކިޔަވަން އުޅޭހިނދު މަރުދުވަފައިވާ ޝައިޠާނާ (ފިތުނަވެރިޔާ) ގެ ކިބައިން ﷲ ގެ ޙަޟްރަތުން ޙިމާޔަތް އެދޭށެވެ. 16:98
- ދަންނާށެވެ. ޖާހިލުކަމުން ކުރެވޭ ނުބައި ކަމެއް ފުއްސެވޭނީ އެ މީހާ ތައުބާވެ އަމިއްލަ ނަފްސު ރަނގަޅު ކުރުމުންނެވެ. 16:119
- (އޭ މުޙައްމަދު ﷺ) ތިބާގެ ވެރިރަސްކަލާނގެ މަގަށް (އެބަހީ: އިސްލާމް ދީނަށް) ޙިކުމަތާއި ރީތި ވަޢުޡުން މީސްތަކުން ގޮވާށެވެ. އަދި އެއުރެންނާ އެންމެ ރަނގަޅު ގޮތުގައި ޖަދަލު ކުރާށެވެ. އެހެން މީހުން ﷲ ގެ މަގަށް ގޮވުން ކުރަންވާނީ ޙިކުމަތާއި އޯގާތެރިކަމާއެކުއެވެ. 16:125
- ﷲ އެކަލާނގެއަށް ބިރުވެތިވާ މީހުންނާއި މުޙްސިނުން (ހެޔޮ ޢަމަލުކުރާ މީހުން) އާއެކުއެވެ. 16:128
- މި ޤުރުއާން އެންމެ ޢަދުލުވެރި އަދި އެންމެ ރަނގަޅު މަގަށް ހިދާޔަތް ދައްކައެވެ. 17:9
- އެއްވެސް މީހަކަށް އަނެއް މީހެއްގެ ފާފަތައް އުފުލައެއް ނުލެވޭނެތެވެ. 17:15
- އާޚިރަތަށް އެދި އަދި އެކަމަށް ޙައްޤުވާ މިންވަރަށް މަސައްކަތް ކޮށް އަދި އޭނާ މުއުމިނަކު ކަމުގައިވާނަމަ ފަހެ އެއުރެންނީ އެއުރެންގެ މަސައްކަތް ޤަދަރުކުރެވި ޝުކުރު ކުރެވި އަދި (ﷲ ގެ ޙަޟްރަތުން) ޖަޒާ ލިބޭނެ މީހުންނެވެ. 17:19
- މައިންބަފައިންނަށް ޢިއްޒަތް ދީ އޯގާތެރިކަމާއެކު މުޢާމަލާ ކުރާށެވެ. މައިންބަފައިންނަށް ކިޔަމަންވާށެވެ. މައިންބަފައިންނަށް ނިކަމެތިކަމުގެ ބަހެއް ނުބުނާށެވެ. އަދި ތިބާގެ ވެރިރަސްކަލާނގެ އަމުރު ކުރައްވައިފިއެވެ. ތިޔަބައިމީހުން އެކަލާނގެ މެނުވީ އެއްވެސް ފަރާތަކަށް އަޅުކަން ނުކުރުމަށެވެ. އަދި ތިޔަބައިމީހުން މައިންބަފައިންނަށް ކިޔަމަންވާށެވެ. އެއުރެންގެ ތެރެއިން އެކަކު ނުވަތަ ދެމީހުންވެސް ތިބާގެ ދިރިއުޅުމުގައި މުސްކުޅިވެއްޖެނަމަ އެއުރެންނަށް ނިކަމެތިކަމުގެ ބަހެއް ނުބުނާށެވެ. އަދި އެއުރެންނަށް އަޑުއުސް ނުކުރާށެވެ. އެހެނެއްކަމަކު އެއުރެންނަށް ޢިއްޒަތުގެ ބަސް ބުނާށެވެ. 17:23
- އަދި ރަޙްމަތުގެ ސަބަބުން އެއުރެންނަށް ކިޔަމަންވުމާއި އިންތިހާއަށް ދާ މަޑުމައިތިރިކަމުގެ ފިޔަތައް ދަށަށް ލާށެވެ. އަދި ބުނާށެވެ. "އަޅުގެ ވެރިރަސްކަލާނގެއެވެ. އަޅާ ކުޑައިރު އަޅާ ބޮޑުކުރެއްވި ފަދައިން އެއުރެންނަށް ތިބާގެ ރަޙްމަތް ލައްވައިފާށެވެ." 17:24
- ހަމަކަށްވަންކަމާއެވެ. އިސްރާފުކުރާ މީހުންނީ ޝައިޠާނުންގެ އަޚުންނެވެ. އަދި ޝައިޠާނާ (ފިތުނަވެރިޔާ – އިބްލީސް) އީ އޭނާގެ ވެރިރަސްކަލާނގެއަށް ދެކޮޅުހަދާ މީހެކެވެ. 17:27
- މުދާ އިސްރާފުކޮށް ނުހޭދަކުރާށެވެ. 17:29
- ފަޤީރުކަމުގެ ބިރުން ދަރިން ނުޤަތުލާށެވެ. 17:31
- ޒިނާ ނުކުރާށެވެ. ކައިވެނީގެ ޙުރުމަތް ދަމައިގަނެ ޒިނާއިން ދުރުވާށެވެ. 17:32
- ތިޔަބައިމީހުން މިންގަނޑު ނަގާހިނދު ފުރިހަމައަށް ނަގާށެވެ. އަދި ސީދާ ތަރާޒޫއަކުން ކިރާށެވެ. އެއީ ރަނގަޅު (މަންފާހުރި) ކަމެކެވެ. އަދި ނިމުންގައި މާ ރަނގަޅެވެ. 17:35
- (އޭ އިންސާނާއެވެ. ނުބުނާށެވެ. ނުވަތަ ނުދެކޭށެވެ. ނުވަތަ ހެކިނުވާށެވެ.) ތިބާއަށް ޢިލްމެއް ނެތް ކަމެއްގެ ފަހަތް ނުލާށެވެ. (މިސާލަކަށް: މީހަކު ބުނުން: "ތިމަންނާ ދެކީމެވެ." ޙަޤީޤަތުގައި އޭނާ ނުދެކޭ ކަމުގައިވިޔަސް، ނުވަތަ "ތިމަންނާ އަޑުއެހީމެވެ." އޭނާ ނާއިވާ ކަމުގައިވިޔަސްއެވެ.) 17:36
- މަޑުމައިތިރިވާށެވެ. އަދި ކިބުރުވެރި ނުވާށެވެ. ކިބުރާއި ބޮޑާކަމާއެކު ބިމުގައި ނުހިނގާށެވެ. ހަމަކަށްވަންކަމާއެވެ. ތިބާއަކަށް ބިން ފަޅައިގެން ނުދެވޭނެއެވެ. އަދި ފަރުބަދަތަކުގެ އުސްމިނަށް ނުދެވޭނެއެވެ. 17:37
- ތިބާގެ ވެރިރަސްކަލާނގެ ތިބާ އެންމެ ރަނގަޅަށް ދެނެވޮޑިގެންވެއެވެ. އެކަލާނގެ އިރާދަކުރައްވައިފިނަމަ ތިޔަބައިމީހުންނަށް ރަޙްމަތް ލައްވާނެއެވެ. ނުވަތަ އެކަލާނގެ އިރާދަކުރައްވައިފިނަމަ ތިޔަބައިމީހުންނަށް ޢަޛާބު ކުރައްވާނެއެވެ. 17:54
- މި ދުނިޔޭގައި ކަނު (އެބަހީ: ﷲ ގެ އާޔަތްތައް ނުދެކި އެކަލާނގެއަށް އީމާން ނުވާ) މީހާ އާޚިރަތުގައިވެސް ކަނުވާނެއެވެ. އަދި މަގުން މާ ބޮޑަށް ފުނގެނިގެންވާނެއެވެ. 17:72
- ނަމާދަށް ކަނޑައެޅިފައިވާ ވަޤުތުތައް ދަމައިގަންނާށެވެ. 17:78
- ހަމަކަށްވަންކަމާއެވެ. ތިމަންރަސްކަލާނގެ މި ޤުރުއާނުގައި މީސްތަކުންނަށް ކޮންމެ ބާވަތެއްގެ މިސާލެއް ފުރިހަމައަށް ބަޔާން ކުރެއްވީމެވެ. އެހެނެއްކަމަކު މީސްތަކުންގެ ގިނަބަޔަކު ކުފުރު މެނުވީ (ޙައްޤު ޤަބޫލުކޮށް އެއްވެސް އެއްޗެއް) ނުޤަބޫލުކުރެތެވެ. 17:89
- ތިމަންރަސްކަލާނގެ މި ޤުރުއާނުގައި މީސްތަކުންނަށް ކޮންމެ ބާވަތެއްގެ މިސާލެއް ބަޔާން ކުރެއްވީމެވެ. އެހެނެއްކަމަކު އިންސާނާ އެންމެ ބޮޑަށް ޖަދަލުކުރާ އެއްޗަކަށް ވެއެވެ. 18:54
- އެއީ އެއުރެންގެ ޖަޒާއެވެ. ނަރަކަމެވެ. އެއީ އެއުރެން ކާފިރުވެ ތިމަންރަސްކަލާނގެ އާޔަތްތަކާއި ތިމަންރަސްކަލާނގެ ރަސޫލުން ފުރައްސާރައެއްގެ ގޮތުގައި ބަލައިގަތުމުންނެވެ. 18:106
- ﷲ އަށް ދަރިކަލަކު ލެއްވުން ނޭކަންވެއެވެ. (މިއީ ނަޞާރާއިން ﷲ އާ ދިމާއަށް ބުނާ ދޮގަށް އިޝާރާތެކެވެ. އެއުރެން ބުނެއެވެ. "ޢީސާ (ޔަސޫޢު) އީ ﷲ ގެ ދަރިކަލެވެ.") އެއުރެން އެކަލާނގެއަށް ޝަރީކު ކުރާ ހުރިހާ ތަކެއްޗަށްވުރެ އެކަލާނގެ މަތިވެރިވެ މާތްވެގެންވެއެވެ. 19:35
- މީސްތަކުންނަށް މަޑުމައިތިރި ބަހުން ވާހަކަ ދައްކާށެވެ. 20:44
- ހެޔޮ ޢަމަލު ކުރުމުގައި އެއްބަޔަކު އަނެއްބަޔަކާ ވާދަ ކުރާށެވެ. 21:90
- ބޭކާރު ވާހަކައިން ދުރުވާށެވެ. 23:3
- ތިޔަބައިމީހުންގެ ޢައުރަ ރައްކާތެރިކުރާށެވެ. 23:5
- ފާފައަށް ދަމައިގަންނަ ހިތް ރައްކާތެރިކުރާށެވެ. 23:97
- އެހެން މީހުންނަށް ޢަފޫކޮށް އެއުރެންގެ ކުށްތައް ފުއްސާށެވެ. 24:22
- އެހެން މީހުންގެ ޚާއްޞަކަން ޤަދަރު ކުރާށެވެ. ޚާއްޞަކޮށް އެއުރެންގެ ގެތަކުގައެވެ. އަވަށްޓެރިންގެ ޙައްޤުތައް އަދާ ކުރާށެވެ. 24:27
- (ފިރިހެނުންނާއި އަންހެނުން ދެބައިމީހުންވެސް) ލޯ ތިރިކޮށް ބަހައްޓާށެވެ. ތިޔަބައިމީހުންގެ ޢައުރައާއި ޢިއްފަތް ރައްކާތެރިކުރާށެވެ. 24:30
- ފޭރާމާއި އަޚްލާޤުގައި ޙަޔާތްތެރިކަން ދަމައިގަންނާށެވެ. 24:31
- ދަންނާށެވެ. ﷲ އެކަލާނގެއަށް އަޅުކަން ކޮށް ހެޔޮ ޢަމަލު ކުރާ މީހުންނަށް އަމާންކަމާއި ސުލްޙަ ދެއްވައެވެ. 24:55
- މައިންބަފައިންގެ ޚާއްޞަ ކޮޓަރިއަށް އިޛުނަ ނުހޯދައި ނުވަނާށެވެ. 24:58
- މަޑުމައިތިރިވެ އިންތިހާއަށް ނުދާށެވެ. 25:63
- ދޮގު ހެކިބުމާއި ޚިޔާނާތުން ދުރުވާށެވެ. 25:72
- އާޚިރަތުގެ ޘަވާބަށް މަސައްކަތް ކުރާށެވެ. އެހެނެއްކަމަކު ދުނިޔޭގެ ކަންތައްތައް ނުހަނދާންނުވާށެވެ. 28:77
- ﷲ އާއެކު އެހެން އެއްވެސް އިލާހަކަށް ދަންނަވާ ނުކުރާށެވެ. 28:88
- ލިވާޠުވުމުގައި ނުހަރަކާށެވެ. 29:29
- ތިޔަބައިމީހުންގެ ހުރިހާ މަސައްކަތެއްގައި އެންމެ މޮޅުކަމަށް މަސައްކަތް ކުރާށެވެ. 29:69
- ނަމާދު ޤާއިމުކޮށް ޘަވާބުގެ ގޮތުގައި ހޭދަ ކުރާށެވެ. 31:4
- ހެޔޮކަމަށް އަމުރު ކޮށް ނުބައިކަމުން ނަހީ ކުރާށެވެ. 31:17
- އަޚްލާޤުގައި ކިބުރުވެރިކަމުން ދުރުވާށެވެ. ބޭކާރު ވާހަކައިން ވަޤުތު ބޭކާރު ނުކުރާށެވެ. 31:18
- ތިޔަބައިމީހުންގެ ހަށިގަނޑާއި އަޑުގެ މިންވަރު މެދުމިންވަރުކޮށް ބަހައްޓާށެވެ. 31:19
- ނަބިއްޔާ މުޙައްމަދު ﷺ ގެ ނަމޫނާއަށް ތަބަޢަވާށެވެ. 33:21
- އަންހެނުން އެއުރެންގެ ޒީނަތާއި ރީތިކަން ފާޅުނުކުރާށެވެ. 33:33
- ހުރިހާ ޙާލަތެއްގައި ތެދު ބުނާށެވެ. 33:70
- ވިސްނާ ފިކުރުކޮށް ޙިކުމަތާއި ފަހުމް ހޯދާށެވެ. 38:29
- ޤުރުއާނުގެ އަމުރުތަކަށް ކިޔަމަންވާށެވެ. 39:23
- ފާފަވެރިޔާ ތައުބާވެ އެކަލާނގެއަށް އެނބުރިއައިފިނަމަ ﷲ ހުރިހާ ފާފަތަކެއް ފުއްސަވައެވެ. 39:53
- ﷲ އަށް އިޚްލާޞްތެރި ދުޢާ ކުރާށެވެ. 40:60
- ނުބައިކަން އެންމެ ރަނގަޅު ގޮތުން ދުރުކުރާށެވެ. 41:34
- ކަންތައްތައް މަޝްވަރާއިން ނިންމާށެވެ. 42:38
- ނަބިއްޔާގެ އަޑުފުޅަށްވުރެ ތިޔަބައިމީހުންގެ އަޑު އުސް ނުކުރާށެވެ. 49:2
- ސިއްރުތައް ރައްކާތެރިކޮށް ޚިޔާނާތުން ދުރުވާށެވެ. 49:6
- ޚިލާފުވާ މީހުންގެ މެދުގައި ޞުލްޙަ ޤާއިމު ކުރާށެވެ. ޚިލާފުތަކުގައި ޞުލްޙަ ހޯދާށެވެ. 49:9
- އެހެން މީހުންށް ފުރައްސާރަ ނުކުރާށެވެ. 49:11
- ޝައްކުކުރުން ދޫކޮށްލާށެވެ. ޖާސޫސުވުމާއި ޣީބަބުނުމުން ދުރުވާށެވެ. އެހެން މީހުންނަށް ބުހުތާން ނުކުރާށެވެ. ނުވަތަ އެއުރެންގެ ނަން ނުގަނާށެވެ. ޣީބަބުނުމާއި ބުހުތާނުގެ ހުރިހާ ސިފައަކުން ދުރުވާށެވެ. ކިބުރުވެރިކަމުން އަނިޔާއަށް ދިއުން ނުދޭށެވެ. 49:12
- ދަންނާށެވެ. މީހަކު މާތްކުރަނީ ހަމައެކަނި ތަޤުވާވެރިކަމެވެ. މީސްތަކުންނާއި ޘަޤާފަތްތަކުގެ ތެރޭގައިވާ ތަފާތުތައް ޤަދަރު ކުރާށެވެ. 49:13
- ދަތުރުވެރިންނަށް ޢިއްޒަތް ދޭށެވެ. 51:26
- ﷲ އާ ދިމާއަށް ތިޔަބައިމީހުންގެ ޒިންމާތައް ހަނދާން ބަހައްޓާށެވެ. 51:56
- މުދާ ޘަވާބުގެ ގޮތުގައި ހޭދަ ކުރާށެވެ. 57:7
- ދަންނާށެވެ. ދީނުގައި ރަހުބާނިއްޔަތު (ކައިވެނި ދޫކޮށް ދުނިޔޭގެ އަރާމުތައް ދޫކޮށްލުން ފަދަ ކަންތައް — ރަހުބާނުން، ނަންނުން ފަދަ ދީނީ ވަޢުދުގެ ދަށުގައި އުޅޭ މީހުން ނުވަތަ އެއުރެން އުޅޭ ޢިމާރާތްތައް) ނެތެވެ. 57:27
- މުދާ ﷲ ހަނދުމަ ކުރުމުން ތިޔަބައިމީހުން ޣާފިލު ނުކުރާށެވެ. 58:11
- ޢިލްމު ލިބިފައިވާ މީހުންނަށް ﷲ މަތީ ދަރަޖައެއް ދެއްވާނެއެވެ. 58:11
- ޣައިރު މުސްލިމުންނާ ރަނގަޅާއި ޢަދުލުވެރި ގޮތުގައި މުޢާމަލާ ކުރާށެވެ. 60:8
- ތިޔަބައިމީހުންގެ އިޢުތިޤާދާއި ޢަމަލުގައި މުނާފިޤުކަމުން ދުރުވާށެވެ. 63:9
- ދަހިވެތިކަމާއި މިސްކިނުވުމުން ދުރުވާށެވެ. 64:16
- ތިޔަބައިމީހުންނަށް ޙަވާލުކުރެވިފައިވާ ވަޙީތައް ރައްކާތެރިކުރާށެވެ. 73:15
- ޤިޔާމަތް ދުވަހަށް ހަނދާން ބަހައްޓާށެވެ. 75:36
- ކެތްތެރިކަމާއި އޯގާތެރިކަމަށް އަމުރު ކުރާށެވެ. 90:17
- އެއުރެންގެ ނަފްސުތައް ޠާހިރުކުރި މީހުން ކާމިޔާބުވެއެވެ. އަދި އެއުރެންގެ ނަފްސުތައް ފަސާދަކުޅަ މީހުން ޚަސާރަވެއެވެ. 91:10
- ބޭނުންޖެހިފައިވާ މީހުން ނުދޫކޮށް ނުފޮނުވާށެވެ. 93:10
- ޢިލްމާއި ފަހުމް ހޯދާށެވެ. ޤުރުއާން ކިޔަވައި ވިސްނާ ފިކުރުކުރާށެވެ. 96:1–5
- ފަޤީރުންނަށް ކާންދިނުމަށް ބާރު އަޅާށެވެ. 107:3
""";
